//! Unix signals that can be sent to tasks via `pueue kill --signal`.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Signal {
    SigInt,
    SigKill,
    SigTerm,
    SigCont,
    SigStop,
}

/// Parse a signal from its name (case insensitive, optional `sig` prefix) or its number.
pub fn parse_signal(input: &str) -> Result<Signal, String> {
    let lower = input.to_ascii_lowercase();
    let name = lower.strip_prefix("sig").unwrap_or(&lower);
    let signal = match name {
        "int" | "2" => Signal::SigInt,
        "kill" | "9" => Signal::SigKill,
        "term" | "15" => Signal::SigTerm,
        "cont" | "18" => Signal::SigCont,
        "stop" | "19" => Signal::SigStop,
        _ => return Err("Matching variant not found".to_string()),
    };
    Ok(signal)
}
