//! Error type and report formatting.
//!
//! Errors carry a chain of messages (outermost first) and a source location.
//! Reports are rendered to stderr in a style mimicking a colourful error report.

use std::fmt;

#[derive(Debug, Clone)]
pub struct Error {
    /// Chain of error messages, the first entry being the outermost context.
    pub chain: Vec<String>,
    /// Source location (`file:line`) shown in the report.
    pub location: Location,
}

#[derive(Debug, Clone, Copy)]
pub struct Location {
    pub file: &'static str,
    pub line: u32,
}

impl Location {
    pub const fn new(file: &'static str, line: u32) -> Self {
        Location { file, line }
    }
}

pub type Result<T> = std::result::Result<T, Error>;

impl Error {
    pub fn new(message: impl Into<String>, location: Location) -> Self {
        Error {
            chain: vec![message.into()],
            location,
        }
    }

    /// Wrap this error with an additional outer context message.
    pub fn context(mut self, message: impl Into<String>) -> Self {
        self.chain.insert(0, message.into());
        self
    }

    /// Replace the location of this error.
    pub fn at(mut self, location: Location) -> Self {
        self.location = location;
        self
    }

    /// The innermost error message.
    pub fn root(&self) -> &str {
        self.chain.last().map(|s| s.as_str()).unwrap_or("")
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.chain.first().map(|s| s.as_str()).unwrap_or(""))
    }
}

/// Format an I/O error in the same way `std::io::Error`'s Display does.
pub fn io_error_string(err: &std::io::Error) -> String {
    err.to_string()
}

/// Indent all lines but the first by the given amount of spaces.
fn indent_continuation(text: &str, indent: usize) -> String {
    let pad = " ".repeat(indent);
    let mut out = String::new();
    for (i, line) in text.split('\n').enumerate() {
        if i > 0 {
            out.push('\n');
            out.push_str(&pad);
        }
        out.push_str(line);
    }
    out
}

/// Render an error report to a string.
pub fn render_report(error: &Error) -> String {
    let mut out = String::new();
    out.push_str("Error: \n");
    for (i, msg) in error.chain.iter().enumerate() {
        out.push_str(&format!(
            "{:>4}: \x1b[91m{}\x1b[0m\n",
            i,
            indent_continuation(msg, 6)
        ));
    }
    out.push('\n');
    out.push_str("Location:\n");
    out.push_str(&format!(
        "   \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m\n",
        error.location.file, error.location.line
    ));
    out.push('\n');
    out.push_str(&backtrace_hint());
    out
}

pub fn backtrace_hint() -> String {
    let mut out = String::new();
    match std::env::var("RUST_BACKTRACE") {
        Ok(value) if value == "full" => {
            out.push_str("\n  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n");
        }
        Ok(value) if value != "0" && !value.is_empty() => {
            out.push_str("\n  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n");
        }
        _ => {
            out.push_str(
                "Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n",
            );
            out.push_str("Run with RUST_BACKTRACE=full to include source snippets.\n");
        }
    }
    out
}

/// Print an error report to stderr.
pub fn report(error: &Error) {
    eprint!("{}", render_report(error));
}

/// Render a panic-style report (used where the reference implementation crashes).
pub fn render_panic(message: &str, location: Location) -> String {
    let mut out = String::new();
    out.push_str("\x1b[31mThe application panicked (crashed).\x1b[0m\n");
    out.push_str(&format!("Message:  \x1b[36m{message}\x1b[0m\n"));
    out.push_str(&format!(
        "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m\n",
        location.file, location.line
    ));
    out.push('\n');
    out.push_str(&backtrace_hint());
    out
}

/// Abort the process in the same way a panic would, printing a panic report.
pub fn panic_exit(message: &str, location: Location) -> ! {
    use std::io::Write;
    let _ = std::io::stdout().flush();
    eprint!("{}", render_panic(message, location));
    std::process::exit(101);
}

/// Convenience macro to create an error with the current location replaced by a fixed one.
#[macro_export]
macro_rules! err {
    ($loc:expr, $($arg:tt)*) => {
        $crate::error::Error::new(format!($($arg)*), $loc)
    };
}
EOF
