/// Print an error report to stderr.
pub fn report(error: &Error) {
    eprint!("{}", render_report(error));
}

/// Render a panic-style report (used where the reference implementation crashes).
pub fn render_panic(message: &str, location: Location) -> String {
    let mut out = String::new();
    out.push_str("\x1b[31mThe application panicked (crashed).\x1b[0m\n");
    out.push_str(&format!("Message:  \x1b[36m{message}\x1b[0m\n"));
    out.push_str(&format!(
        "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m\n",
        location.file, location.line
    ));
    out.push('\n');
    out.push_str(&backtrace_hint());
    out
}

/// Abort the process in the same way a panic would, printing a panic report.
pub fn panic_exit(message: &str, location: Location) -> ! {
    use std::io::Write;
    let _ = std::io::stdout().flush();
    eprint!("{}", render_panic(message, location));
    std::process::exit(101);
}

/// Convenience macro to create an error with the current location replaced by a fixed one.
#[macro_export]
macro_rules! err {
    ($loc:expr, $($arg:tt)*) => {
        $crate::error::Error::new(format!($($arg)*), $loc)
    };
}
