            Some(path) => expand_home(path),
            None => default_pueue_directory(),
        }
    }

    pub fn runtime_directory(&self) -> PathBuf {
        if let Some(path) = &self.runtime_directory {
            expand_home(path)
        } else if let Ok(path) = std::env::var("XDG_RUNTIME_DIR") {
            PathBuf::from(path)
        } else {
            self.pueue_directory()
        }
    }

    pub fn unix_socket_path(&self) -> PathBuf {
        match &self.unix_socket_path {
            Some(path) => expand_home(path),
            None => self
                .runtime_directory()
                .join(format!("pueue_{}.socket", username())),
        }
    }

    pub fn daemon_cert(&self) -> PathBuf {
        match &self.daemon_cert {
            Some(path) => expand_home(path),
            None => self.pueue_directory().join("certs").join("daemon.cert"),
        }
    }

    pub fn daemon_key(&self) -> PathBuf {
        match &self.daemon_key {
            Some(path) => expand_home(path),
            None => self.pueue_directory().join("certs").join("daemon.key"),
        }
    }

    pub fn shared_secret_path(&self) -> PathBuf {
        match &self.shared_secret_path {
            Some(path) => expand_home(path),
            None => self.pueue_directory().join("shared_secret"),
        }
    }

    pub fn alias_file(&self) -> PathBuf {
        match &self.alias_file {
            Some(path) => expand_home(path),
            None => default_config_directory().join("pueue_aliases.yml"),
        }
    }
}

const READ_LOCATION: Location = Location::new("pueue/src/bin/pueue.rs", 51);

fn read_config_file(path: &Path) -> Result<Settings> {
    let content = std::fs::read_to_string(path).map_err(|err| {
        Error::new(
            format!(
                "I/O error at path {:?} while opening config file:\n{}",
                path, err
            ),
            READ_LOCATION,
        )
        .context("Failed to read configuration.")
    })?;
    parse_config(&content)
}

fn parse_config(content: &str) -> Result<Settings> {
    serde_yaml::from_str::<Settings>(content).map_err(|err| {
        Error::new(
            format!("Error while reading configuration:\n{}", err),
            READ_LOCATION,
        )
        .context("Failed to read configuration.")
    })
}

/// Load the settings. Returns the settings and whether a config file was found.
pub fn read_settings(explicit_path: Option<&Path>) -> Result<(Settings, bool)> {
    if let Some(path) = explicit_path {
        let settings = read_config_file(path)?;
        return Ok((settings, true));
    }
    if let Ok(path) = std::env::var("PUEUE_CONFIG_PATH") {
        let settings = read_config_file(Path::new(&path))?;
        return Ok((settings, true));
    }

    info("pueue_lib::settings", "Parsing config files", "pueue_lib/src/settings.rs", 391);
    let candidates = vec![
        default_config_directory().join("pueue.yml"),
        PathBuf::from("./pueue.yml"),
    ];
    for path in candidates {
        info(
            "pueue_lib::settings",
            &format!("Checking path: {:?}", path),
            "pueue_lib/src/settings.rs",
            396,
        );
        if path.exists() && path.is_file() {
            info(
                "pueue_lib::settings",
                &format!("Found config file at: {:?}", path),
                "pueue_lib/src/settings.rs",
                399,
            );
            let settings = read_config_file(&path)?;
            return Ok((settings, true));
        }
    }

    info(
        "pueue_lib::settings",
        "No config file found. Use default config.",
        "pueue_lib/src/settings.rs",
        413,
    );
    let _ = trace;
    Ok((Settings::default(), false))
}

impl Settings {
    /// Apply a named profile on top of the base settings.
    pub fn load_profile(&mut self, profile: &str) -> Result<()> {
        let Some(nested) = self.profiles.remove(profile) else {
            return Err(Error::new(
                format!(
                    "Error while reading configuration:\nCouldn't find profile with name \"{}\"",
                    profile
                ),
                Location::new("pueue/src/bin/pueue.rs", 55),
            ));
        };
        self.client = nested.client;
        self.daemon = nested.daemon;
        self.shared = nested.shared;
        Ok(())
    }
}
