//! Minimal logging facility that mimics the output format of the reference implementation.

use std::sync::atomic::{AtomicU8, Ordering};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

/// 0 = uninitialised, otherwise the maximum level that is printed.
static MAX_LEVEL: AtomicU8 = AtomicU8::new(2);
/// Whether the verbose "pretty" format is used.
static PRETTY: AtomicU8 = AtomicU8::new(0);

pub fn init(verbosity: u8) {
    let level = match verbosity {
        0 => Level::Warn,
        1 => Level::Info,
        2 => Level::Debug,
        _ => Level::Trace,
    };
    MAX_LEVEL.store(level as u8, Ordering::Relaxed);
    PRETTY.store(if verbosity >= 4 { 1 } else { 0 }, Ordering::Relaxed);
}

pub fn enabled(level: Level) -> bool {
    (level as u8) <= MAX_LEVEL.load(Ordering::Relaxed)
}

fn level_str(level: Level) -> &'static str {
    match level {
        Level::Error => "ERROR",
        Level::Warn => " WARN",
        Level::Info => " INFO",
        Level::Debug => "DEBUG",
        Level::Trace => "TRACE",
    }
}

fn level_color(level: Level) -> &'static str {
    match level {
        Level::Error => "31",
        Level::Warn => "33",
        Level::Info => "32",
        Level::Debug => "34",
        Level::Trace => "35",
    }
}

/// A structured field attached to a log event.
pub struct Field<'a> {
    pub name: &'a str,
    /// Compact (`{:#?}`) representation.
    pub pretty_value: String,
    /// Single-line (`{:?}`) representation.
    pub value: String,
}

pub fn log_event(level: Level, target: &str, message: &str, fields: &[Field], file: &str, line: u32) {
    if !enabled(level) {
        return;
    }
    let time = chrono::Local::now().format("%H:%M:%S").to_string();
    let color = level_color(level);
    let mut out = String::new();
    if PRETTY.load(Ordering::Relaxed) == 1 {
        out.push_str(&format!(
            "  \x1b[2m{time}\x1b[0m \x1b[{color}m{}\x1b[0m \x1b[1;{color}m{target}\x1b[0m\x1b[{color}m: \x1b[{color}m{message}",
            level_str(level)
        ));
        for field in fields {
            out.push_str(&format!(
                ", \x1b[1;{color}m{}\x1b[0m\x1b[{color}m: {}",
                field.name, field.value
            ));
        }
        out.push_str("\x1b[0m\n");
        out.push_str(&format!(
            "    \x1b[2;3mat\x1b[0m {file}:{line} \x1b[2;3mon\x1b[0m main\n\n"
        ));
    } else {
        out.push_str(&format!(
            "\x1b[2m{time}\x1b[0m \x1b[{color}m{}\x1b[0m \x1b[2m{target}\x1b[0m\x1b[2m:\x1b[0m {message}",
            level_str(level)
        ));
        for field in fields {
            out.push_str(&format!(
                " \x1b[3m{}\x1b[0m\x1b[2m=\x1b[0m{}",
                field.name, field.pretty_value
            ));
        }
        out.push('\n');
    }
    eprint!("{out}");
}

pub fn error(target: &str, message: &str, file: &str, line: u32) {
    log_event(Level::Error, target, message, &[], file, line);
}

pub fn warn(target: &str, message: &str, file: &str, line: u32) {
    log_event(Level::Warn, target, message, &[], file, line);
}

pub fn info(target: &str, message: &str, file: &str, line: u32) {
    log_event(Level::Info, target, message, &[], file, line);
}

pub fn debug(target: &str, message: &str, file: &str, line: u32) {
    log_event(Level::Debug, target, message, &[], file, line);
}

pub fn trace(target: &str, message: &str, file: &str, line: u32) {
    log_event(Level::Trace, target, message, &[], file, line);
}
