//! Shared state types that are exchanged with the daemon.

use std::collections::{BTreeMap, HashMap};
use std::fmt;
use std::path::PathBuf;

use chrono::{DateTime, Local};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum TaskResult {
    Success,
    Failed(i32),
    FailedToSpawn(String),
    Killed,
    Errored,
    DependencyFailed,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum TaskStatus {
    Stashed {
        enqueue_at: Option<DateTime<Local>>,
    },
    Queued {
        enqueued_at: DateTime<Local>,
    },
    Running {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
    },
    Paused {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
    },
    Done {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
        end: DateTime<Local>,
        result: TaskResult,
    },
    Locked {
        previous_status: Box<TaskStatus>,
    },
}

impl fmt::Display for TaskStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            TaskStatus::Stashed { .. } => "Stashed",
            TaskStatus::Queued { .. } => "Queued",
            TaskStatus::Running { .. } => "Running",
            TaskStatus::Paused { .. } => "Paused",
            TaskStatus::Done { .. } => "Done",
            TaskStatus::Locked { .. } => "Locked",
        };
        write!(f, "{name}")
    }
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Task {
    pub id: usize,
    pub created_at: DateTime<Local>,
    pub original_command: String,
    pub command: String,
    pub path: PathBuf,
    pub envs: HashMap<String, String>,
    pub group: String,
    pub dependencies: Vec<usize>,
    pub priority: i32,
    pub label: Option<String>,
    pub status: TaskStatus,
}

impl fmt::Debug for Task {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Task")
            .field("id", &self.id)
            .field("original_command", &self.original_command)
            .field("command", &self.command)
            .field("path", &self.path)
            .field("envs", &"hidden")
            .field("group", &self.group)
            .field("dependencies", &self.dependencies)
            .field("label", &self.label)
            .field("status", &self.status)
            .field("priority", &self.priority)
            .finish()
    }
}

impl Task {
    pub fn is_running(&self) -> bool {
        matches!(
            self.status,
            TaskStatus::Running { .. } | TaskStatus::Paused { .. }
        )
    }

    pub fn is_done(&self) -> bool {
        matches!(self.status, TaskStatus::Done { .. })
    }

    pub fn is_queued(&self) -> bool {
        matches!(
            self.status,
            TaskStatus::Queued { .. } | TaskStatus::Stashed { .. }
        )
    }

    pub fn failed(&self) -> bool {
        match &self.status {
            TaskStatus::Done { result, .. } => !matches!(result, TaskResult::Success),
            _ => false,
        }
    }

    pub fn start(&self) -> Option<DateTime<Local>> {
        match &self.status {
            TaskStatus::Running { start, .. }
            | TaskStatus::Paused { start, .. }
            | TaskStatus::Done { start, .. } => Some(*start),
            _ => None,
        }
    }

    pub fn end(&self) -> Option<DateTime<Local>> {
        match &self.status {
            TaskStatus::Done { end, .. } => Some(*end),
            _ => None,
        }
    }

    pub fn enqueued_at(&self) -> Option<DateTime<Local>> {
        match &self.status {
            TaskStatus::Queued { enqueued_at }
            | TaskStatus::Running { enqueued_at, .. }
            | TaskStatus::Paused { enqueued_at, .. }
            | TaskStatus::Done { enqueued_at, .. } => Some(*enqueued_at),
            _ => None,
        }
    }

    pub fn enqueue_at(&self) -> Option<DateTime<Local>> {
        match &self.status {
            TaskStatus::Stashed { enqueue_at } => *enqueue_at,
            _ => None,
        }
    }
}

