//! Network client: connection setup, handshake and message framing.

use std::io::{Read, Write};
use std::net::TcpStream;
use std::os::unix::net::UnixStream;
use std::path::Path;

use crate::error::{Error, Location, Result};
use crate::logging::{self, debug, warn};
use crate::message::{Request, Response};
use crate::settings::Settings;

/// The protocol version the client expects from the daemon.
pub const PROTOCOL_VERSION: &str = "0.31.1";

const CLIENT_RS: &str = "/workspace/pueue_lib/src/network/client.rs";
const PROTOCOL_RS: &str = "pueue_lib/src/network/protocol.rs";

pub enum Stream {
    Unix(UnixStream),
    Tcp(TcpStream),
}

impl Read for Stream {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        match self {
            Stream::Unix(s) => s.read(buf),
            Stream::Tcp(s) => s.read(buf),
        }
    }
}

impl Write for Stream {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self {
            Stream::Unix(s) => s.write(buf),
            Stream::Tcp(s) => s.write(buf),
        }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Stream::Unix(s) => s.flush(),
            Stream::Tcp(s) => s.flush(),
        }
    }
}

pub struct Client {
    stream: Stream,
}

/// Placeholder location used for protocol errors; callers replace it with their own.
pub const NO_LOCATION: Location = Location::new("/workspace/pueue/src/client/commands/mod.rs", 106);

/// Read exactly `buf.len()` bytes. Reports "early eof" when the stream ends prematurely.
fn read_exact(stream: &mut Stream, buf: &mut [u8]) -> std::io::Result<()> {
    let mut filled = 0;
    while filled < buf.len() {
        match stream.read(&mut buf[filled..]) {
            Ok(0) => {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "early eof",
                ))
            }
            Ok(n) => filled += n,
            Err(err) if err.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        }
    }
    Ok(())
}

pub fn send_bytes(stream: &mut Stream, payload: &[u8]) -> Result<()> {
    let header = (payload.len() as u64).to_be_bytes();
    stream.write_all(&header).map_err(|err| {
        Error::new(
            format!("I/O error while sending request size header:\n{err}"),
            NO_LOCATION,
        )
    })?;
    for chunk in payload.chunks(1400) {
        stream.write_all(chunk).map_err(|err| {
            Error::new(
                format!("I/O error while sending payload chunk:\n{err}"),
                NO_LOCATION,
            )
        })?;
    }
    Ok(())
}

pub fn receive_bytes(stream: &mut Stream) -> Result<Vec<u8>> {
    let mut header = [0u8; 8];
    read_exact(stream, &mut header).map_err(|err| {
        Error::new(
            format!("I/O error while reading request size header:\n{err}"),
            NO_LOCATION,
        )
    })?;
    let message_size = u64::from_be_bytes(header) as usize;

    let mut payload: Vec<u8> = Vec::with_capacity(message_size.min(1 << 20));
    while payload.len() < message_size {
        let remaining = message_size - payload.len();
        let mut chunk = vec![0u8; remaining.min(1400)];
        let received = stream.read(&mut chunk).map_err(|err| {
            Error::new(
                format!("I/O error while reading next chunk:\n{err}"),
                NO_LOCATION,
            )
        })?;
        if received == 0 {
            return Err(Error::new(
                "Connection went away while receiving payload.",
                NO_LOCATION,
            ));
        }
        payload.extend_from_slice(&chunk[..received]);
    }
    Ok(payload)
}

impl Client {
    /// Connect to the daemon and perform the handshake.
    pub fn new(settings: &Settings, secret: &[u8]) -> Result<Self> {
        let stream = if settings.shared.use_unix_socket {
            let path = settings.shared.unix_socket_path();
            connect_unix(&path).map_err(|err| {
                err.context("Failed to initialize stream.")
                    .context("Failed to initialize client.")
                    .at(Location::new(CLIENT_RS, 85))
            })?
        } else {
            let address = format!("{}:{}", settings.shared.host, settings.shared.port);
            let stream = TcpStream::connect(&address).map_err(|err| {
                Error::new(
                    format!("I/O error while connecting to daemon. Did you start it?:\n{err}"),
                    Location::new(CLIENT_RS, 85),
                )
                .context("Failed to initialize stream.")
                .context("Failed to initialize client.")
            })?;
            Stream::Tcp(stream)
        };
        let mut client = Client { stream };

        // Send the secret.
        send_bytes(&mut client.stream, secret).map_err(|err| {
            err.context("Failed to send secret during handshake with daemon.")
                .context("Failed to initialize client.")
                .at(Location::new(CLIENT_RS, 93))
        })?;

        // Receive the daemon's version.
        let version_bytes = receive_bytes(&mut client.stream).map_err(|err| {
            err.context("Failed to receive version during handshake with daemon.")
                .context("Failed to initialize client.")
                .at(Location::new(CLIENT_RS, 97))
        })?;
        let version = String::from_utf8_lossy(&version_bytes).to_string();
        if version != PROTOCOL_VERSION {
            warn(
                "pueue_lib::network::client",
                &format!(
                    "Different protocol version detected '{version}'. Consider updating and restarting the daemon."
                ),
                CLIENT_RS,
                101,
            );
        }

        Ok(client)
    }

    pub fn send_request(&mut self, request: Request) -> Result<()> {
        if logging::enabled(logging::Level::Debug) {
            debug(
                "pueue_lib::network::protocol",
                &format!("Sending message: {request:#?}"),
                PROTOCOL_RS,
                50,
            );
        }
        let mut payload = Vec::new();
        ciborium::into_writer(&request, &mut payload).map_err(|err| {
            Error::new(format!("Failed to serialize message:\n{err:?}"), NO_LOCATION)
        })?;
        send_bytes(&mut self.stream, &payload)
    }

    pub fn receive_response(&mut self) -> Result<Response> {
        let payload = receive_bytes(&mut self.stream)?;
        if payload.is_empty() {
            return Err(Error::new("Got an empty payload", NO_LOCATION));
        }
        match ciborium::from_reader::<Response, _>(payload.as_slice()) {
            Ok(response) => {
                if logging::enabled(logging::Level::Debug) {
                    debug(
                        "pueue_lib::network::protocol",
                        &format!("Received message: {response:#?}"),
                        PROTOCOL_RS,
                        199,
                    );
                }
                Ok(response)
            }
            Err(err) => {
                // Try to show a readable version of whatever we received.
                match ciborium::from_reader::<ciborium::Value, _>(payload.as_slice()) {
                    Ok(value) => Err(Error::new(
                        format!("Got unexpected but valid message. Are you up-to-date?:\n{value:#?}"),
                        NO_LOCATION,
                    )),
                    Err(_) => Err(Error::new(
                        format!("Couldn't deserialize message:\n{err:?}"),
                        NO_LOCATION,
                    )),
                }
            }
        }
    }
}

fn connect_unix(path: &Path) -> Result<Stream> {
    match UnixStream::connect(path) {
        Ok(stream) => Ok(Stream::Unix(stream)),
        Err(err) => Err(Error::new(
            format!(
                "I/O error at path {:?} while connecting to daemon. Did you start it?:\n{}",
                path, err
            ),
            NO_LOCATION,
        )),
    }
}
EOF
echo ok"}

