#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Arrangement {
    /// Columns are as wide as their content.
    Disabled,
    /// Columns are shrunk and content wrapped to fit the available width.
    Dynamic,
}

#[derive(Debug, Clone)]
pub struct ColumnSettings {
    pub padding: (usize, usize),
    pub alignment: Option<Alignment>,
}

impl Default for ColumnSettings {
    fn default() -> Self {
        ColumnSettings {
            padding: (1, 1),
            alignment: None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Table {
    pub header: Option<Row>,
    pub rows: Vec<Row>,
    pub preset: Preset,
    pub columns: Vec<ColumnSettings>,
    pub arrangement: Arrangement,
    /// Explicit width to arrange within. If unset and dynamic, the terminal width is used.
    pub width: Option<usize>,
    pub style_enabled: bool,
}

impl Table {
    pub fn new() -> Self {
        Table {
            header: None,
            rows: Vec::new(),
            preset: Preset::nothing(),
            columns: Vec::new(),
            arrangement: Arrangement::Disabled,
            width: None,
            style_enabled: true,
        }
    }

    pub fn set_header(&mut self, cells: Vec<Cell>) -> &mut Self {
        self.ensure_columns(cells.len());
        self.header = Some(Row::new(cells));
        self
    }

    pub fn add_row(&mut self, cells: Vec<Cell>) -> &mut Self {
        self.ensure_columns(cells.len());
        self.rows.push(Row::new(cells));
        self
    }

    fn ensure_columns(&mut self, count: usize) {
        while self.columns.len() < count {
            self.columns.push(ColumnSettings::default());
        }
    }

    pub fn column_mut(&mut self, index: usize) -> Option<&mut ColumnSettings> {
        self.columns.get_mut(index)
    }

    fn column_count(&self) -> usize {
        self.columns.len()
    }

    /// Iterate over all cells of a column (header included).
    fn column_cells(&self, index: usize) -> Vec<&Cell> {
        let mut cells = Vec::new();
        if let Some(header) = &self.header {
            if let Some(cell) = header.cells.get(index) {
                cells.push(cell);
            }
        }
        for row in &self.rows {
            if let Some(cell) = row.cells.get(index) {
                cells.push(cell);
            }
        }
        cells
    }

    /// Maximum content width of each column.
    fn max_content_widths(&self) -> Vec<usize> {
        (0..self.column_count())
            .map(|index| {
                self.column_cells(index)
                    .iter()
                    .flat_map(|cell| cell.lines())
                    .map(|line| line.width())
                    .max()
                    .unwrap_or(0)
            })
            .collect()
    }

    /// Determine the available width for dynamic arrangement.
    fn available_width(&self) -> Option<usize> {
        if let Some(width) = self.width {
            return Some(width);
        }
        use std::io::IsTerminal;
        if std::io::stdout().is_terminal() {
            if let Ok((width, _)) = crossterm::terminal::size() {
                return Some(width as usize);
            }
        }
        None
    }

    /// Calculate the content width of every column.
    fn arrange(&self) -> Vec<usize> {
        let max_widths = self.max_content_widths();
        let columns = self.column_count();
        match self.arrangement {
            Arrangement::Disabled => max_widths,
            Arrangement::Dynamic => match self.available_width() {
                None => max_widths,
                Some(table_width) => self.arrange_dynamic(table_width, &max_widths),
            },
        }
    }

    fn arrange_dynamic(&self, table_width: usize, max_widths: &[usize]) -> Vec<usize> {
        let columns = self.column_count();
        let mut widths: Vec<Option<usize>> = vec![None; columns];
        if columns == 0 {
            return Vec::new();
        }

        // Step 1: available content width.
        let mut border_count = 0;
        if self.preset.draw_left_border() {
            border_count += 1;
        }
        if self.preset.draw_right_border() {
            border_count += 1;
        }
        if self.preset.draw_vertical_lines() {
            border_count += columns.saturating_sub(1);
        }
        let mut remaining_width = table_width.saturating_sub(border_count);
        for settings in &self.columns {
            remaining_width =
                remaining_width.saturating_sub(settings.padding.0 + settings.padding.1);
        }

        // Step 2-4: columns that need less than the average.
        let mut remaining_columns = columns;
        let mut found_smaller = true;
        while found_smaller {
            found_smaller = false;
            if remaining_columns == 0 {
                break;
            }
            let average_space = remaining_width / remaining_columns;
            if average_space == 0 {
                break;
            }
            for index in 0..columns {
                if widths[index].is_some() {
                    continue;
                }
                if max_widths[index] < average_space {
                    widths[index] = Some(max_widths[index]);
                    remaining_width = remaining_width.saturating_sub(max_widths[index]);
                    found_smaller = true;
                    remaining_columns -= 1;
                }
            }
        }

        if remaining_columns == 0 {
            return widths.into_iter().map(|w| w.unwrap_or(0)).collect();
        }

        // Step 5: optimize space after splitting cells.
        let mut average_space = remaining_width / remaining_columns;
        let mut found_smaller = true;
        'outer: while found_smaller {
            found_smaller = false;
            for index in 0..columns {
                if widths[index].is_some() {
                    continue;
                }
                let longest_line = self.longest_line_after_split(index, average_space);
                let remaining_space = average_space.saturating_sub(longest_line);
                if remaining_space >= 3 {
                    widths[index] = Some(longest_line);
                    remaining_width = remaining_width.saturating_sub(longest_line);
                    remaining_columns -= 1;
                    if remaining_columns == 0 {
                        break 'outer;
                    }
                    average_space = remaining_width / remaining_columns;
                    found_smaller = true;
                }
            }
        }

        if remaining_columns == 0 {
            return widths.into_iter().map(|w| w.unwrap_or(0)).collect();
        }

        // Step 6: distribute the remaining space equally.
        let average_space = remaining_width / remaining_columns;
        let mut excess = remaining_width - average_space * remaining_columns;
        for index in 0..columns {
            if widths[index].is_some() {
                continue;
            }
            let width = if excess > 0 {
                excess -= 1;
                average_space + 1
            } else {
                average_space
            };
            widths[index] = Some(width);
        }

        widths.into_iter().map(|w| w.unwrap_or(0)).collect()
    }

    fn longest_line_after_split(&self, index: usize, width: usize) -> usize {
        let mut longest = 0;
        for cell in self.column_cells(index) {
            for line in cell.lines() {
                if line.width() > width {
                    for part in split_line(&line, width, ' ') {
                        longest = longest.max(part.width());
                    }
                } else {
                    longest = longest.max(line.width());
                }
            }
        }
        longest
    }

    /// Render the table into lines of text.
    pub fn render(&self) -> String {
        let widths = self.arrange();
        let columns = self.column_count();
        let preset = &self.preset;
        let mut lines: Vec<String> = Vec::new();

        let total_widths: Vec<usize> = (0..columns)
            .map(|i| widths[i] + self.columns[i].padding.0 + self.columns[i].padding.1)
            .collect();

        let draw_vertical = preset.draw_vertical_lines();
        let draw_left = preset.draw_left_border();
        let draw_right = preset.draw_right_border();

        // Helper to draw a horizontal line.
        let horizontal = |left: Option<char>,
                          fill: Option<char>,
                          middle: Option<char>,
                          right: Option<char>|
         -> String {
            let mut line = String::new();
            if draw_left {
                line.push(left.unwrap_or(' '));
            }
            for (i, width) in total_widths.iter().enumerate() {
                if i != 0 && draw_vertical {
                    line.push(middle.unwrap_or(' '));
                }
                for _ in 0..*width {
                    line.push(fill.unwrap_or(' '));
                }
            }
            if draw_right {
                line.push(right.unwrap_or(' '));
            }
            line
        };

        if preset.draw_top_border() {
            lines.push(horizontal(
                preset.top_left_corner,
                preset.top_border,
                preset.top_border_intersections,
                preset.top_right_corner,
            ));
        }

        if let Some(header) = &self.header {
            lines.extend(self.render_row(header, &widths, draw_left, draw_right, draw_vertical));
            if preset.draw_header_lines() {
                lines.push(horizontal(
                    preset.left_header_intersection,
                    preset.header_lines,
                    preset.middle_header_intersections,
                    preset.right_header_intersection,
                ));
            }
        }

        for (i, row) in self.rows.iter().enumerate() {
            if i != 0 && preset.draw_horizontal_lines() {
                lines.push(horizontal(
                    preset.left_border_intersections,
                    preset.horizontal_lines,
                    preset.middle_intersections,
                    preset.right_border_intersections,
                ));
            }
            lines.extend(self.render_row(row, &widths, draw_left, draw_right, draw_vertical));
        }

        if preset.draw_bottom_border() {
            lines.push(horizontal(
                preset.bottom_left_corner,
                preset.bottom_border,
                preset.bottom_border_intersections,
                preset.bottom_right_corner,
            ));
        }

        lines.join("\n")
    }

    fn render_row(
        &self,
        row: &Row,
        widths: &[usize],
        draw_left: bool,
        draw_right: bool,
        draw_vertical: bool,
    ) -> Vec<String> {
        let columns = self.column_count();
        // Prepare the (wrapped, aligned, padded, styled) lines of each cell.
        let mut cell_lines: Vec<Vec<String>> = Vec::with_capacity(columns);
        for index in 0..columns {
            let settings = &self.columns[index];
            let width = widths[index];
            let mut rendered = Vec::new();
            if let Some(cell) = row.cells.get(index) {
                let mut raw_lines = Vec::new();
                for line in cell.lines() {
                    if line.width() > width {
                        raw_lines.extend(split_line(&line, width, ' '));
                    } else {
                        raw_lines.push(line);
                    }
                }
                for line in raw_lines {
                    let alignment = cell
                        .alignment
                        .or(settings.alignment)
                        .unwrap_or(Alignment::Left);
                    let aligned = align_line(line, width, alignment, settings.padding);
                    let styled = if self.style_enabled {
                        crate::style::style_line(aligned, cell.fg, &cell.attributes)
                    } else {
                        aligned
                    };
                    rendered.push(styled);
                }
            }
            cell_lines.push(rendered);
        }

        let row_height = cell_lines.iter().map(|c| c.len()).max().unwrap_or(1).max(1);
        let mut out = Vec::new();
        for line_index in 0..row_height {
            let mut line = String::new();
            if draw_left {
                line.push(self.preset.left_border.unwrap_or(' '));
            }
            for index in 0..columns {
                if index != 0 && draw_vertical {
                    line.push(self.preset.vertical_lines.unwrap_or(' '));
                }
                match cell_lines[index].get(line_index) {
                    Some(content) => line.push_str(content),
                    None => {
                        let settings = &self.columns[index];
                        let total = widths[index] + settings.padding.0 + settings.padding.1;
                        line.push_str(&" ".repeat(total));
                    }
                }
            }
            if draw_right {
                line.push(self.preset.right_border.unwrap_or(' '));
            }
            out.push(line);
        }
        out
    }
}

impl Default for Table {
    fn default() -> Self {
        Table::new()
    }
}

impl std::fmt::Display for Table {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.render())
    }
}

fn align_line(line: String, width: usize, alignment: Alignment, padding: (usize, usize)) -> String {
    let remaining = width.saturating_sub(line.width());
    let aligned = match alignment {
        Alignment::Left => format!("{line}{}", " ".repeat(remaining)),
        Alignment::Right => format!("{}{line}", " ".repeat(remaining)),
        Alignment::Center => {
            let left = (remaining as f32 / 2f32).ceil() as usize;
            let right = (remaining as f32 / 2f32).floor() as usize;
            format!("{}{line}{}", " ".repeat(left), " ".repeat(right))
        }
    };
    format!(
        "{}{aligned}{}",
        " ".repeat(padding.0),
        " ".repeat(padding.1)
    )
}

/// Split a word that is longer than the allowed width into a part that fits and the remainder.
fn split_long_word(allowed_width: usize, word: &str) -> (String, String) {
    let mut current_width = 0;
    let mut split_at = 0;
    for (index, ch) in word.char_indices() {
        let char_width = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if current_width + char_width > allowed_width {
            break;
        }
        current_width += char_width;
        split_at = index + ch.len_utf8();
    }
    (word[..split_at].to_string(), word[split_at..].to_string())
}

/// Split a line into multiple lines that fit into the given width.
pub fn split_line(line: &str, content_width: usize, delimiter: char) -> Vec<String> {
    let mut lines = Vec::new();
    let mut elements: Vec<&str> = line.split(delimiter).collect();
    elements.reverse();

    let mut current_line = String::new();
    while let Some(next) = elements.pop() {
        let current_length = current_line.width();
        let next_length = next.width();

        let mut added_length = next_length + current_length;
        if !current_line.is_empty() {
            added_length += 1;
        }
        let mut remaining_width = content_width.saturating_sub(current_length);
        if !current_line.is_empty() {
            remaining_width = remaining_width.saturating_sub(1);
        }

        if added_length <= content_width {
            if !current_line.is_empty() {
                current_line.push(delimiter);
            }
            current_line += next;
        } else if next_length <= content_width {
            lines.push(current_line);
            current_line = next.to_string();
        } else {
            if !current_line.is_empty() {
                current_line.push(delimiter);
            }
            let (first, mut remaining) = split_long_word(remaining_width, next);
            current_line += &first;
            lines.push(current_line);

            while remaining.width() > content_width {
                let (first, rest) = split_long_word(content_width, &remaining);
                lines.push(first);
                remaining = rest;
            }
            current_line = remaining;
        }
    }
    if !current_line.is_empty() {
        lines.push(current_line);
    }
    lines
}
