//! Output styling helpers (colors and attributes).

use std::io::IsTerminal;

use crossterm::style::{Attribute, Color, ContentStyle, StyledContent, Stylize};

use crate::settings::Settings;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorChoice {
    Auto,
    Never,
    Always,
}

#[derive(Debug, Clone)]
pub struct OutputStyle {
    /// Whether styling is enabled at all.
    pub enabled: bool,
    /// Whether dark mode colors should be used.
    pub dark_mode: bool,
}

impl OutputStyle {
    pub fn new(settings: &Settings, choice: ColorChoice) -> Self {
        let enabled = match choice {
            ColorChoice::Auto => std::io::stdout().is_terminal(),
            ColorChoice::Always => true,
            ColorChoice::Never => false,
        };
        OutputStyle {
            enabled,
            dark_mode: settings.client.dark_mode,
        }
    }

    /// Adjust a color for dark mode.
    pub fn map_color(&self, color: Color) -> Color {
        if self.dark_mode {
            match color {
                Color::Green => Color::DarkGreen,
                Color::Red => Color::DarkRed,
                Color::Yellow => Color::DarkYellow,
                other => other,
            }
        } else {
            color
        }
    }

    /// Style a piece of text with an optional color and attribute.
    pub fn style_text<T: ToString>(
        &self,
        text: T,
        color: Option<Color>,
        attribute: Option<Attribute>,
    ) -> String {
        let text = text.to_string();
        if !self.enabled {
            return text;
        }
        let mut styled: StyledContent<String> = text.stylize();
        if let Some(color) = color {
            styled = styled.with(self.map_color(color));
        }
        if let Some(attribute) = attribute {
            styled = styled.attribute(attribute);
        }
        styled.to_string()
    }

    /// Build a styled table cell.
    pub fn styled_cell<T: ToString>(
        &self,
        text: T,
        color: Option<Color>,
        attribute: Option<Attribute>,
    ) -> crate::table::Cell {
        let mut cell = crate::table::Cell::new(text.to_string());
        if self.enabled {
            if let Some(color) = color {
                cell.fg = Some(self.map_color(color));
            }
            if let Some(attribute) = attribute {
                cell.attributes.push(attribute);
            }
        }
        cell
    }
}

/// Apply crossterm styling to an already padded line, mimicking how cells are styled.
pub fn style_line(line: String, fg: Option<Color>, attributes: &[Attribute]) -> String {
    if fg.is_none() && attributes.is_empty() {
        return line;
    }
    let mut style = ContentStyle::new();
    style.foreground_color = fg;
    for attribute in attributes {
        style.attributes.set(*attribute);
    }
    StyledContent::new(style, line).to_string()
}
