            send_request_and_handle(&mut ctx, Request::Stash(StashRequest { tasks, enqueue_at }))
        }
        ("enqueue", Some(sub)) => {
            let ids = task_ids(sub, "task_ids");
            let group = string(sub, "group");
            let tasks = selection_from_params(flag(sub, "all"), group.as_deref(), &ids);
            let enqueue_at = sub
                .get_one::<chrono::DateTime<chrono::Local>>("delay")
                .copied();
            send_request_and_handle(
                &mut ctx,
                Request::Enqueue(EnqueueRequest { tasks, enqueue_at }),
            )
        }
        ("start", Some(sub)) => {
            let ids = task_ids(sub, "task_ids");
            let group = string(sub, "group");
            let tasks = selection_from_params(flag(sub, "all"), group.as_deref(), &ids);
            send_request_and_handle(&mut ctx, Request::Start(StartRequest { tasks }))
        }
        ("restart", Some(sub)) => restart::restart(&mut ctx, sub),
        ("pause", Some(sub)) => {
            let ids = task_ids(sub, "task_ids");
            let group = string(sub, "group");
            let tasks = selection_from_params(flag(sub, "all"), group.as_deref(), &ids);
            let wait = flag(sub, "wait");
            send_request_and_handle(&mut ctx, Request::Pause(PauseRequest { tasks, wait }))
        }
        ("kill", Some(sub)) => {
            let ids = task_ids(sub, "task_ids");
            let group = string(sub, "group");
            let tasks = selection_from_params(flag(sub, "all"), group.as_deref(), &ids);
            if settings.client.show_confirmation_questions {
                handle_user_confirmation("kill", &ids)?;
            }
            let signal = sub.get_one::<crate::signal::Signal>("signal").copied();
            send_request_and_handle(&mut ctx, Request::Kill(KillRequest { tasks, signal }))
        }
        ("send", Some(sub)) => {
            let request = SendRequest {
                task_id: *sub.get_one::<usize>("task_id").unwrap(),
                input: string(sub, "input").unwrap_or_default(),
            };
            send_request_and_handle(&mut ctx, Request::Send(request))
        }
        ("edit", Some(sub)) => edit::edit(&mut ctx, sub),
        ("env", Some(sub)) => {
            let request = match sub.subcommand() {
                Some(("set", m)) => EnvRequest::Set {
                    task_id: *m.get_one::<usize>("task_id").unwrap(),
                    key: string(m, "key").unwrap_or_default(),
                    value: string(m, "value").unwrap_or_default(),
                },
                Some(("unset", m)) => EnvRequest::Unset {
                    task_id: *m.get_one::<usize>("task_id").unwrap(),
                    key: string(m, "key").unwrap_or_default(),
                },
                _ => unreachable!(),
            };
            send_request_and_handle(&mut ctx, Request::Env(request))
        }
        ("group", Some(sub)) => group::group(&mut ctx, sub),
        ("status", sub) => status::status(&mut ctx, sub),
        ("log", Some(sub)) => log::log(&mut ctx, sub),
        ("follow", Some(sub)) => follow::follow(&mut ctx, sub),
        ("wait", Some(sub)) => wait::wait(&mut ctx, sub),
        ("clean", Some(sub)) => {
            let request = CleanRequest {
                successful_only: flag(sub, "successful_only"),
                group: string(sub, "group"),
            };
            send_request_and_handle(&mut ctx, Request::Clean(request))
        }
        ("reset", Some(sub)) => reset::reset(&mut ctx, sub),
        ("shutdown", Some(_)) => {
            send_request_and_handle(&mut ctx, Request::DaemonShutdown(Shutdown::Graceful))
        }
        ("parallel", Some(sub)) => {
            let parallel_tasks = sub.get_one::<usize>("parallel_tasks").copied();
            let group = string(sub, "group");
            match parallel_tasks {
                Some(parallel_tasks) => {
