//! Helpers to render `Debug`-like representations of the parsed subcommands.

use clap::ArgMatches;

use super::{flag, string, strings, task_ids};

#[derive(Debug, Clone)]
pub enum DebugValue {
    Unit(String),
    Str(String),
    Raw(String),
    Option(Option<Box<DebugValue>>),
    List(Vec<DebugValue>),
    Struct(String, Vec<(String, DebugValue)>),
}

impl DebugValue {
    pub fn raw<T: ToString>(value: T) -> Self {
        DebugValue::Raw(value.to_string())
    }

    pub fn string<T: ToString>(value: T) -> Self {
        DebugValue::Str(value.to_string())
    }

    pub fn bool(value: bool) -> Self {
        DebugValue::Raw(value.to_string())
    }

    pub fn option<T>(value: Option<T>, f: impl Fn(T) -> DebugValue) -> Self {
        DebugValue::Option(value.map(|v| Box::new(f(v))))
    }

    pub fn list<T>(values: impl IntoIterator<Item = T>, f: impl Fn(T) -> DebugValue) -> Self {
        DebugValue::List(values.into_iter().map(f).collect())
    }

    /// Render like `{:?}`.
    pub fn compact(&self) -> String {
        match self {
            DebugValue::Unit(name) => name.clone(),
            DebugValue::Str(value) => format!("{value:?}"),
            DebugValue::Raw(value) => value.clone(),
            DebugValue::Option(None) => "None".to_string(),
            DebugValue::Option(Some(value)) => format!("Some({})", value.compact()),
            DebugValue::List(values) => {
                let inner: Vec<String> = values.iter().map(|v| v.compact()).collect();
                format!("[{}]", inner.join(", "))
            }
            DebugValue::Struct(name, fields) => {
                if fields.is_empty() {
                    return name.clone();
                }
                let inner: Vec<String> = fields
                    .iter()
                    .map(|(field, value)| format!("{field}: {}", value.compact()))
                    .collect();
                format!("{name} {{ {} }}", inner.join(", "))
            }
        }
    }

    /// Render like `{:#?}`.
    pub fn pretty(&self) -> String {
        let mut out = String::new();
        self.pretty_into(&mut out, 0);
        out
    }

    fn pretty_into(&self, out: &mut String, indent: usize) {
        let pad = " ".repeat(indent);
        let inner_pad = " ".repeat(indent + 4);
        match self {
            DebugValue::Unit(name) => out.push_str(name),
            DebugValue::Str(value) => out.push_str(&format!("{value:?}")),
            DebugValue::Raw(value) => out.push_str(value),
            DebugValue::Option(None) => out.push_str("None"),
            DebugValue::Option(Some(value)) => {
                out.push_str("Some(\n");
                out.push_str(&inner_pad);
                value.pretty_into(out, indent + 4);
                out.push_str(",\n");
                out.push_str(&pad);
                out.push(')');
            }
            DebugValue::List(values) => {
                if values.is_empty() {
                    out.push_str("[]");
                    return;
                }
                out.push_str("[\n");
                for value in values {
                    out.push_str(&inner_pad);
                    value.pretty_into(out, indent + 4);
                    out.push_str(",\n");
                }
                out.push_str(&pad);
                out.push(']');
            }
            DebugValue::Struct(name, fields) => {
                if fields.is_empty() {
                    out.push_str(name);
                    return;
                }
                out.push_str(name);
                out.push_str(" {\n");
                for (field, value) in fields {
                    out.push_str(&inner_pad);
                    out.push_str(field);
                    out.push_str(": ");
                    value.pretty_into(out, indent + 4);
                    out.push_str(",\n");
                }
                out.push_str(&pad);
                out.push('}');
            }
        }
    }
}

fn ids(sub: &ArgMatches, name: &str) -> DebugValue {
    DebugValue::list(task_ids(sub, name), DebugValue::raw)
}

fn opt_string(sub: &ArgMatches, name: &str) -> DebugValue {
    DebugValue::option(string(sub, name), DebugValue::string)
}

fn opt_usize(sub: &ArgMatches, name: &str) -> DebugValue {
    DebugValue::option(sub.get_one::<usize>(name).copied(), DebugValue::raw)
}

fn opt_datetime(sub: &ArgMatches, name: &str) -> DebugValue {
    DebugValue::option(
        sub.get_one::<chrono::DateTime<chrono::Local>>(name).copied(),
        |dt| DebugValue::raw(format!("{dt:?}")),
    )
}

fn s(name: &str, fields: Vec<(&str, DebugValue)>) -> DebugValue {
    DebugValue::Struct(
