//! The `status` subcommand.

use clap::ArgMatches;

use super::{get_state, Context};
use crate::display::state::print_state;
use crate::error::{Location, Result};
use crate::query::parse_query;
use crate::state::Task;

pub use super::debug::subcommand_debug as debug_value;

pub fn subcommand_debug(name: &str, sub: Option<&ArgMatches>) -> (String, String) {
    let value = debug_value(name, sub);
    (value.pretty(), value.compact())
}

pub fn status(ctx: &mut Context, sub: Option<&ArgMatches>) -> Result<()> {
    let query_parts: Vec<String> = sub.map(|s| super::strings(s, "query")).unwrap_or_default();
    let json = sub.map(|s| super::flag(s, "json")).unwrap_or(false);
    let group = sub.and_then(|s| super::string(s, "group"));

    let mut state = get_state(ctx.client).map_err(|err| {
        err.at(Location::new(
            "/workspace/pueue/src/client/commands/state/mod.rs",
            40,
        ))
    })?;

    // Parse the query and apply it to the tasks.
    let query = parse_query(&query_parts.join(" "))?;
    let mut tasks: Vec<Task> = state.tasks.values().cloned().collect();
    if let Some(group) = &group {
        tasks.retain(|task| &task.group == group);
    }
    let tasks = query.apply(tasks);

    if json {
        state.tasks = tasks.into_iter().map(|task| (task.id, task)).collect();
        println!("{}", serde_json::to_string(&state).unwrap());
        return Ok(());
    }

    let output = print_state(
        &state,
        tasks,
        query.selected_columns.as_deref(),
        group.as_deref(),
