//! Decoder for the snappy framing format (as used for compressed task logs).

use std::fmt;

#[derive(Debug)]
pub struct SnappyError(String);

impl fmt::Display for SnappyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "snappy: {}", self.0)
    }
}

impl std::error::Error for SnappyError {}

const STREAM_IDENTIFIER: &[u8] = b"\xff\x06\x00\x00sNaPpY";
const MAX_BLOCK_SIZE: usize = 1 << 16;

fn read_varint(input: &[u8]) -> Option<(u64, usize)> {
    let mut result: u64 = 0;
    let mut shift = 0;
    for (i, byte) in input.iter().enumerate() {
        if i >= 10 {
            return None;
        }
        result |= ((byte & 0x7f) as u64) << shift;
        if byte & 0x80 == 0 {
            return Some((result, i + 1));
        }
        shift += 7;
    }
    None
}

/// Decompress a raw snappy block.
pub fn decompress_block(input: &[u8]) -> Result<Vec<u8>, SnappyError> {
    let (len, mut pos) =
        read_varint(input).ok_or_else(|| SnappyError("corrupt input (bad varint)".into()))?;
    let len = len as usize;
    let mut out: Vec<u8> = Vec::with_capacity(len);

    while pos < input.len() {
        let tag = input[pos];
        pos += 1;
        match tag & 0x03 {
            0 => {
                // Literal
                let mut literal_len = (tag >> 2) as usize;
                if literal_len >= 60 {
                    let extra = literal_len - 59;
                    if pos + extra > input.len() {
                        return Err(SnappyError("corrupt input (literal length)".into()));
                    }
                    let mut value: usize = 0;
                    for i in 0..extra {
                        value |= (input[pos + i] as usize) << (8 * i);
                    }
                    literal_len = value;
                    pos += extra;
                }
                literal_len += 1;
                if pos + literal_len > input.len() {
                    return Err(SnappyError("corrupt input (literal data)".into()));
                }
                out.extend_from_slice(&input[pos..pos + literal_len]);
                pos += literal_len;
            }
            1 => {
                // Copy with 1-byte offset
                let copy_len = 4 + ((tag >> 2) & 0x07) as usize;
                if pos >= input.len() {
                    return Err(SnappyError("corrupt input (copy offset)".into()));
                }
                let offset = (((tag >> 5) as usize) << 8) | input[pos] as usize;
                pos += 1;
                copy(&mut out, offset, copy_len)?;
            }
            2 => {
                let copy_len = 1 + (tag >> 2) as usize;
                if pos + 2 > input.len() {
                    return Err(SnappyError("corrupt input (copy offset)".into()));
                }
                let offset = input[pos] as usize | ((input[pos + 1] as usize) << 8);
                pos += 2;
                copy(&mut out, offset, copy_len)?;
            }
            _ => {
                let copy_len = 1 + (tag >> 2) as usize;
                if pos + 4 > input.len() {
                    return Err(SnappyError("corrupt input (copy offset)".into()));
                }
                let offset = input[pos] as usize
                    | ((input[pos + 1] as usize) << 8)
                    | ((input[pos + 2] as usize) << 16)
                    | ((input[pos + 3] as usize) << 24);
                pos += 4;
                copy(&mut out, offset, copy_len)?;
            }
        }
    }

    if out.len() != len {
        return Err(SnappyError(format!(
            "corrupt input (expected {len} bytes but got {})",
            out.len()
        )));
    }
    Ok(out)
}

fn copy(out: &mut Vec<u8>, offset: usize, len: usize) -> Result<(), SnappyError> {
    if offset == 0 || offset > out.len() {
        return Err(SnappyError("corrupt input (invalid copy offset)".into()));
    }
    let start = out.len() - offset;
    for i in 0..len {
        let byte = out[start + i];
        out.push(byte);
    }
    Ok(())
}

fn crc32c(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFF_FFFF;
    for byte in data {
        crc ^= *byte as u32;
        for _ in 0..8 {
            crc = if crc & 1 != 0 {
                (crc >> 1) ^ 0x82F6_3B78
            } else {
                crc >> 1
            };
        }
    }
    crc ^ 0xFFFF_FFFF
}

fn masked_crc(data: &[u8]) -> u32 {
    let crc = crc32c(data);
    crc.rotate_right(15).wrapping_add(0xa282_ead8)
}

/// Decompress a complete snappy frame stream.
pub fn decompress_frames(input: &[u8]) -> Result<Vec<u8>, SnappyError> {
    let mut out = Vec::new();
    let mut pos = 0;

    if input.len() < STREAM_IDENTIFIER.len() {
        if input.is_empty() {
            return Ok(out);
        }
        return Err(SnappyError(
            "corrupt input (missing stream header)".to_string(),
        ));
    }
    if &input[..STREAM_IDENTIFIER.len()] != STREAM_IDENTIFIER {
        let chunk_type = input[0];
        return Err(SnappyError(format!(
            "corrupt input (expected stream header but got unexpected chunk type byte {chunk_type})"
        )));
    }
    pos += STREAM_IDENTIFIER.len();

    while pos < input.len() {
        if pos + 4 > input.len() {
            return Err(SnappyError("corrupt input (truncated chunk header)".into()));
        }
        let chunk_type = input[pos];
        let len = input[pos + 1] as usize
            | ((input[pos + 2] as usize) << 8)
            | ((input[pos + 3] as usize) << 16);
        pos += 4;
        if pos + len > input.len() {
            return Err(SnappyError("corrupt input (truncated chunk)".into()));
        }
        let chunk = &input[pos..pos + len];
        pos += len;

        match chunk_type {
            0xff => {
                if chunk != &STREAM_IDENTIFIER[4..] {
                    return Err(SnappyError("corrupt input (invalid stream header)".into()));
                }
            }
            0x00 => {
                if chunk.len() < 4 {
                    return Err(SnappyError("corrupt input (chunk too small)".into()));
                }
                let expected = u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                let data = decompress_block(&chunk[4..])?;
                if data.len() > MAX_BLOCK_SIZE {
                    return Err(SnappyError("corrupt input (block too large)".into()));
                }
                if masked_crc(&data) != expected {
                    return Err(SnappyError("corrupt input (checksum mismatch)".into()));
                }
                out.extend_from_slice(&data);
            }
            0x01 => {
                if chunk.len() < 4 {
                    return Err(SnappyError("corrupt input (chunk too small)".into()));
                }
                let expected = u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                let data = &chunk[4..];
                if masked_crc(data) != expected {
                    return Err(SnappyError("corrupt input (checksum mismatch)".into()));
                }
                out.extend_from_slice(data);
            }
            0x02..=0x7f => {
                return Err(SnappyError(format!(
                    "corrupt input (unsupported chunk type {chunk_type})"
                )));
            }
            _ => {
                // Reserved skippable chunk, ignore.
            }
        }
    }
    Ok(out)
}
