//! The `log` subcommand.

use std::collections::BTreeMap;

use clap::ArgMatches;

use super::{flag, selection_from_params, string, task_ids, Context};
use crate::display::log::{print_log, read_local_log_text};
use crate::error::{Location, Result};
use crate::message::{LogRequest, Request, Response, TaskLogResponse};

const LOG_RS: &str = "/workspace/pueue/src/client/commands/log.rs";

pub fn log(ctx: &mut Context, sub: &ArgMatches) -> Result<()> {
    let ids = task_ids(sub, "task_ids");
    let group = string(sub, "group");
    let all = flag(sub, "all");
    let json = flag(sub, "json");
    let full = flag(sub, "full");
    let lines = if full {
        None
    } else {
        Some(sub.get_one::<usize>("lines").copied().unwrap_or(15))
    };

    let tasks = selection_from_params(all, group.as_deref(), &ids);
    let request = LogRequest {
        tasks,
        send_logs: !ctx.settings.client.read_local_logs,
        lines,
    };

    ctx.client
        .send_request(Request::Log(request))
        .map_err(|err| err.at(Location::new(LOG_RS, 45)))?;
    let response = ctx
        .client
        .receive_response()
        .map_err(|err| err.at(Location::new(LOG_RS, 46)))?;

    match response {
        Response::Log(task_logs) => {
            print_logs(ctx, task_logs, json, lines);
            Ok(())
        }
        other => super::handle_response(ctx.style, other),
    }
}

#[derive(serde::Serialize)]
struct JsonTaskLog<'a> {
    task: &'a crate::state::Task,
    output: String,
}

fn print_logs(
    ctx: &mut Context,
    mut task_logs: BTreeMap<usize, TaskLogResponse>,
    json: bool,
    lines: Option<usize>,
) {
    if json {
        let mut map: BTreeMap<usize, JsonTaskLog> = BTreeMap::new();
        for (id, task_log) in &task_logs {
            let output = if ctx.settings.client.read_local_logs {
                read_local_log_text(*id, ctx.settings, lines)
            } else {
                match &task_log.output {
                    Some(bytes) => match crate::snappy::decompress_frames(bytes) {
                        Ok(data) => String::from_utf8_lossy(&data).to_string(),
                        Err(err) => format!("(Pueue error) Failed to decompress log output: {err}"),
                    },
                    None => String::new(),
                }
            };
            map.insert(
                *id,
                JsonTaskLog {
                    task: &task_log.task,
                    output,
                },
            );
        }
        println!("{}", serde_json::to_string(&map).unwrap());
        return;
    }

    // Only tasks that have (or had) output are shown.
    let printable: Vec<usize> = task_logs
        .iter()
        .filter(|(_, log)| {
            matches!(
                log.task.status,
                crate::state::TaskStatus::Done { .. }
                    | crate::state::TaskStatus::Running { .. }
                    | crate::state::TaskStatus::Paused { .. }
            )
        })
        .map(|(id, _)| *id)
        .collect();

    let mut iter = printable.iter().peekable();
    while let Some(id) = iter.next() {
        let task_log = task_logs.get_mut(id).unwrap();
        print_log(task_log, ctx.style, ctx.settings, lines);
        if iter.peek().is_some() {
            println!();
        }
    }
}
