/// Seek the file to the start of the line that is `amount` newlines away from the end.
/// Returns `true` if the whole file is covered (less lines than requested).
pub fn seek_to_last_lines(file: &mut std::fs::File, amount: usize) -> io::Result<bool> {
    let len = file.metadata()?.len();
    let mut found_lines = 0usize;
    let mut position = len;
    let chunk_size: u64 = 4096;
    let mut buffer = vec![0u8; chunk_size as usize];
    while position > 0 {
        let read_size = position.min(chunk_size);
        position -= read_size;
        file.seek(SeekFrom::Start(position))?;
        let buf = &mut buffer[..read_size as usize];
        file.read_exact(buf)?;
        for (i, byte) in buf.iter().enumerate().rev() {
            if *byte != b'\n' {
                continue;
            }
            found_lines += 1;
            if found_lines != amount + 1 {
                continue;
            }
            let target = position + i as u64 + 1;
            file.seek(SeekFrom::Start(target))?;
            return Ok(false);
        }
    }
    file.seek(SeekFrom::Start(0))?;
    Ok(true)
}

/// Print the task information header (box with the status and a table with details).
pub fn print_task_info(task: &Task, style: &OutputStyle) {
    let task_cell = style.styled_cell(format!("Task {}: ", task.id), None, Some(Attribute::Bold));
    let (exit_status, color) = match &task.status {
        TaskStatus::Paused { .. } => ("paused".to_string(), Color::White),
        TaskStatus::Running { .. } => ("running".to_string(), Color::Yellow),
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => ("completed successfully".to_string(), Color::Green),
            TaskResult::Failed(exit_code) => {
                (format!("failed with exit code {exit_code}"), Color::Red)
            }
            TaskResult::FailedToSpawn(_) => ("Failed to spawn".to_string(), Color::Red),
            TaskResult::Killed => ("killed by system or user".to_string(), Color::Red),
            TaskResult::Errored => ("some IO error.\n Check daemon log.".to_string(), Color::Red),
            TaskResult::DependencyFailed => ("dependency failed".to_string(), Color::Red),
        },
        other => (other.to_string(), Color::White),
    };
    let status_cell = style.styled_cell(exit_status, Some(color), None);

    let mut table = Table::new();
    table.preset = Preset::utf8_borders_only();
    table.add_row(vec![task_cell, status_cell]);
    eprintln!("{}", table.render());

    let mut table = Table::new();
    table.preset = Preset::nothing();
    table.add_row(vec![
        style.styled_cell("Command:", None, Some(Attribute::Bold)),
        Cell::new(task.command.clone()),
    ]);
    table.add_row(vec![
        style.styled_cell("Path:", None, Some(Attribute::Bold)),
        Cell::new(task.path.to_string_lossy().to_string()),
    ]);
    if let Some(label) = &task.label {
        table.add_row(vec![
            style.styled_cell("Label:", None, Some(Attribute::Bold)),
            Cell::new(label.clone()),
        ]);
    }
    if let Some(start) = task.start() {
        table.add_row(vec![
            style.styled_cell("Start:", None, Some(Attribute::Bold)),
            Cell::new(start.to_rfc2822()),
        ]);
    }
    if let Some(end) = task.end() {
        table.add_row(vec![
            style.styled_cell("End:", None, Some(Attribute::Bold)),
            Cell::new(end.to_rfc2822()),
        ]);
    }
    if let Some(first) = table.column_mut(0) {
        first.alignment = Some(Alignment::Right);
        first.padding = (0, 0);
    }
    eprintln!("{}", table.render());
}

/// Print the log of a single task.
pub fn print_log(
    task_log: &mut TaskLogResponse,
    style: &OutputStyle,
    settings: &Settings,
    lines: Option<usize>,
) {
    let task = &task_log.task;
    if !matches!(
        task.status,
        TaskStatus::Done { .. } | TaskStatus::Running { .. } | TaskStatus::Paused { .. }
    ) {
        return;
    }

    print_task_info(task, style);

    if settings.client.read_local_logs {
        print_local_log(task.id, style, settings, lines);
    } else if task_log.output.is_some() {
        print_remote_log(task_log, style, lines);
    } else {
        eprintln!("Logs requested from pueue daemon, but none received. Please report this bug.");
    }
}

fn output_header(style: &OutputStyle, lines: Option<usize>, output_complete: bool) -> String {
    let mut line_info = String::new();
    if !output_complete {
        line_info = lines.map_or(String::new(), |lines| {
            style.style_text(format!(" (last {lines} lines)"), None, Some(Attribute::Bold))
        });
    }
    let text = style.style_text("output:", Some(Color::Green), Some(Attribute::Bold));
    format!("\n{text}{line_info}")
}

fn print_local_log(task_id: usize, style: &OutputStyle, settings: &Settings, lines: Option<usize>) {
    let mut file = match get_log_file_handle(task_id, &settings.shared.pueue_directory()) {
        Ok(file) => file,
        Err(err) => {
            eprintln!("Failed to get log file handle: {err}");
            return;
        }
    };

    let Ok(metadata) = file.metadata() else {
        return;
    };
    if metadata.len() == 0 {
        return;
    }

    let mut output_complete = true;
    if let Some(lines) = lines {
        match seek_to_last_lines(&mut file, lines) {
            Ok(complete) => output_complete = complete,
            Err(err) => {
                eprintln!("Failed reading local log file: {err}");
                return;
            }
        }
    }

    eprintln!("{}", output_header(style, lines, output_complete));

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    if let Err(err) = io::copy(&mut file, &mut handle) {
        eprintln!("Failed reading local log file: {err}");
    }
    let _ = handle.flush();
}

fn print_remote_log(task_log: &mut TaskLogResponse, style: &OutputStyle, lines: Option<usize>) {
    let Some(bytes) = task_log.output.take() else {
        return;
    };
    if bytes.is_empty() {
        return;
    }

    println!("{}", output_header(style, lines, task_log.output_complete));

    match crate::snappy::decompress_frames(&bytes) {
        Ok(data) => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            let _ = handle.write_all(&data);
            let _ = handle.flush();
        }
        Err(err) => {
            eprintln!("Error while parsing stdout: {err}");
        }
    }
}

/// Read the output of a task's local log file as text for json output.
pub fn read_local_log_text(task_id: usize, settings: &Settings, lines: Option<usize>) -> String {
    let mut file = match get_log_file_handle(task_id, &settings.shared.pueue_directory()) {
        Ok(file) => file,
        Err(err) => return format!("(Pueue error) Failed to get log file handle: {err}"),
    };
    let mut content = Vec::new();
    if let Err(err) = file.read_to_end(&mut content) {
        return format!("(Pueue error) Failed to read local log file: {err}");
    }
    let content = String::from_utf8_lossy(&content).to_string();
    match lines {
        Some(lines) => {
            let all: Vec<&str> = content.lines().collect();
            let start = all.len().saturating_sub(lines);
            all[start..].join("\n")
        }
        None => content,
    }
}
