//! The `wait` subcommand.

use std::collections::HashMap;
use std::thread::sleep;
use std::time::Duration;

use chrono::Local;
use clap::ArgMatches;
use crossterm::style::{Attribute, Color};

use super::{flag, get_state, selection_from_params, string, task_ids, Context};
use crate::error::Result;
use crate::message::TaskSelection;
use crate::state::{Task, TaskResult, TaskStatus};
use crate::style::OutputStyle;
use crate::wait_status::WaitTargetStatus;

pub fn wait(ctx: &mut Context, sub: &ArgMatches) -> Result<()> {
    let ids = task_ids(sub, "task_ids");
    let group = string(sub, "group");
    let all = flag(sub, "all");
    let quiet = flag(sub, "quiet");
    let target_status = sub
        .get_one::<WaitTargetStatus>("status")
        .copied()
        .unwrap_or(WaitTargetStatus::Done);

    let selection = selection_from_params(all, group.as_deref(), &ids);
    wait_for(ctx, selection, quiet, target_status)
}

pub fn wait_for(
    ctx: &mut Context,
    selection: TaskSelection,
    quiet: bool,
    target_status: WaitTargetStatus,
) -> Result<()> {
    let mut first_run = true;
    let mut watched_tasks: HashMap<usize, TaskStatus> = HashMap::new();

    loop {
        let state = get_state(ctx.client)?;
        let tasks: Vec<&Task> = match &selection {
            TaskSelection::TaskIds(ids) => state
                .tasks
                .values()
                .filter(|task| ids.contains(&task.id))
                .collect(),
            TaskSelection::Group(group) => state
                .tasks
                .values()
                .filter(|task| &task.group == group)
                .collect(),
            TaskSelection::All => state.tasks.values().collect(),
        };

        if tasks.is_empty() {
            println!("No tasks found for selection {selection:?}");
            return Ok(());
        }

        let current_time = Local::now().format("%H:%M:%S").to_string();

        for task in &tasks {
            let Some(previous_status) = watched_tasks.get(&task.id).cloned() else {
                // Finished tasks aren't tracked.
                if task.is_done() {
                    continue;
                }
                watched_tasks.insert(task.id, task.status.clone());
                if !quiet {
                    log_new_task(task, ctx.style, first_run, &current_time);
                }
                continue;
            };

            if previous_status == task.status {
                continue;
            }

            if task.is_done() {
                watched_tasks.remove(&task.id);
            } else {
                watched_tasks.insert(task.id, task.status.clone());
            }
            if !quiet {
                log_status_change(&previous_status, task, ctx.style, &current_time);
            }
        }

        // In "success" mode, abort as soon as a task failed.
        if target_status == WaitTargetStatus::Success && tasks.iter().any(|task| task.failed()) {
            std::process::exit(1);
        }

        if tasks
            .iter()
            .all(|task| reached_target_status(task, target_status))
        {
            break;
        }

        first_run = false;
        sleep(Duration::from_millis(2000));
    }

    Ok(())
}

fn reached_target_status(task: &Task, target: WaitTargetStatus) -> bool {
    match target {
        WaitTargetStatus::Queued => matches!(
            task.status,
            TaskStatus::Queued { .. }
                | TaskStatus::Running { .. }
                | TaskStatus::Paused { .. }
                | TaskStatus::Done { .. }
        ),
        WaitTargetStatus::Running => matches!(
            task.status,
            TaskStatus::Running { .. } | TaskStatus::Paused { .. } | TaskStatus::Done { .. }
        ),
        WaitTargetStatus::Done => matches!(task.status, TaskStatus::Done { .. }),
        WaitTargetStatus::Success => matches!(
            task.status,
            TaskStatus::Done {
                result: TaskResult::Success,
                ..
            }
        ),
    }
}

fn status_color(status: &TaskStatus) -> Color {
    match status {
        TaskStatus::Running { .. } => Color::Green,
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => Color::Green,
            _ => Color::Red,
        },
        _ => Color::White,
    }
}

fn log_new_task(task: &Task, style: &OutputStyle, first_run: bool, current_time: &str) {
    let status = style.style_text(&task.status, Some(status_color(&task.status)), None);
    let id = style.style_text(task.id, None, Some(Attribute::Bold));
    if !first_run {
        println!("{current_time} - New task {id} with status {status}");
        return;
    }
    if task.is_running() {
        println!("{current_time} - Found active Task {id} with status {status}");
    }
}

fn log_status_change(previous: &TaskStatus, task: &Task, style: &OutputStyle, current_time: &str) {
    let id = style.style_text(task.id, None, Some(Attribute::Bold));
    if let TaskStatus::Done { result, .. } = &task.status {
        let text = match result {
            TaskResult::Success => {
                let status = style.style_text("0", Some(Color::Green), None);
                format!("Task {id} succeeded with {status}")
            }
            TaskResult::DependencyFailed => {
                let status = style.style_text("failed dependencies", Some(Color::Red), None);
                format!("Task {id} failed due to {status}")
            }
            TaskResult::FailedToSpawn(_) => {
                let status = style.style_text("failed to spawn", Some(Color::Red), None);
                format!("Task {id} {status}")
            }
            TaskResult::Failed(exit_code) => {
                let status =
                    style.style_text(exit_code, Some(Color::Red), Some(Attribute::Bold));
                format!("Task {id} failed with {status}")
            }
            TaskResult::Errored => {
                let status = style.style_text("IO error", Some(Color::Red), Some(Attribute::Bold));
                format!("Task {id} experienced an {status}.")
            }
            TaskResult::Killed => {
                let status = style.style_text("killed", Some(Color::Red), None);
                format!("Task {id} has been {status}")
            }
        };
        println!("{current_time} - {text}");
        return;
    }

    let new_status = style.style_text(&task.status, Some(status_color(&task.status)), None);
    let previous_status = style.style_text(previous, Some(status_color(previous)), None);
    println!("{current_time} - Task {id} changed from {previous_status} to {new_status}");
}
