pub fn follow_task(ctx: &mut Context, task_id: Option<usize>, lines: Option<usize>) -> Result<()> {
    // Determine which task should be followed.
    let task_id = match task_id {
        Some(task_id) => task_id,
        None => {
            let state = get_state(ctx.client)?;
            let running_ids: Vec<usize> = state
                .tasks
                .values()
                .filter(|task| task.is_running())
                .map(|task| task.id)
                .collect();
            match running_ids.len() {
                0 => {
                    return Err(Error::new(
                        "There are no running tasks.",
                        Location::new(FOLLOW_RS, 114),
                    ))
                }
                1 => running_ids[0],
                _ => {
                    let ids = running_ids
                        .iter()
                        .map(|id| id.to_string())
                        .collect::<Vec<String>>()
                        .join(", ");
                    return Err(Error::new(
                        format!(
                            "Multiple tasks are running, please select one of the following: {ids}"
                        ),
                        Location::new(FOLLOW_RS, 123),
                    ));
                }
            }
        }
    };

    if ctx.settings.client.read_local_logs {
        local_follow(ctx, task_id, lines)
    } else {
        remote_follow(ctx, task_id, lines)
    }
}

/// Wait until the task exists and has been started.
fn wait_for_task_start(ctx: &mut Context, task_id: usize) -> Result<()> {
    loop {
        let state = get_state_for_task(ctx)?;
        match state.tasks.get(&task_id) {
            Some(task) => {
                if !matches!(
                    task.status,
                    TaskStatus::Queued { .. } | TaskStatus::Stashed { .. } | TaskStatus::Locked { .. }
                ) {
                    return Ok(());
                }
            }
            None => {
                eprintln!("Pueue: The task to be followed doesn't exist.");
                std::process::exit(1);
            }
        }
        sleep(Duration::from_millis(1000));
    }
}

fn get_state_for_task(ctx: &mut Context) -> Result<crate::state::State> {
    ctx.client.send_request(Request::Status)?;
    let response = ctx.client.receive_response()?;
    match response {
        Response::Status(state) => Ok(*state),
        _ => crate::error::panic_exit(
            "internal error: entered unreachable code",
            Location::new(super::MOD_RS, 124),
        ),
    }
}

fn local_follow(ctx: &mut Context, task_id: usize, lines: Option<usize>) -> Result<()> {
    wait_for_task_start(ctx, task_id)?;

    let pueue_directory = ctx.settings.shared.pueue_directory();
    let mut handle = match get_log_file_handle(task_id, &pueue_directory) {
        Ok(handle) => handle,
        Err(err) => {
            println!("Failed to get log file handles: {err}");
            return Ok(());
        }
    };
    let path = log_path(task_id, &pueue_directory);

    let stdout = io::stdout();

    if let Some(lines) = lines {
        if let Err(err) = seek_to_last_lines(&mut handle, lines) {
            println!("Error seeking to last lines from log: {err}");
        }
    }

    let log_check_interval: u64 = 250;
    let task_check_interval = log_check_interval * 2;
    let mut last_check: u64 = 0;
    loop {
        if !path.exists() {
            println!("File has gone away. Did somebody remove the task?");
            return Ok(());
        }

        // Read everything that has been appended since the last iteration.
        {
            let mut handle_out = stdout.lock();
            let mut buffer = Vec::new();
            match handle.read_to_end(&mut buffer) {
                Ok(_) => {
                    if let Err(err) = handle_out.write_all(&buffer) {
                        println!("Error while reading file: {err}");
                        return Ok(());
                    }
                }
                Err(err) => {
                    println!("Error while reading file: {err}");
                    return Ok(());
                }
            }
            if let Err(err) = handle_out.flush() {
                println!("Error while flushing stdout: {err}");
                return Ok(());
            }
        }
        // Keep the read position.
        let _ = handle.stream_position();

        if last_check % task_check_interval == 0 {
            let state = get_state_for_task(ctx)?;
            let Some(task) = state.tasks.get(&task_id) else {
                println!("Pueue: The followed task has been removed.");
                return Ok(());
            };
            if !task.is_running() {
                return Ok(());
            }
        }

        last_check += log_check_interval;
        sleep(Duration::from_millis(log_check_interval));
    }
}

fn remote_follow(ctx: &mut Context, task_id: usize, lines: Option<usize>) -> Result<()> {
    let request = StreamRequest {
        tasks: TaskSelection::TaskIds(vec![task_id]),
        lines,
    };
    ctx.client
        .send_request(Request::Stream(request))
        .map_err(|err| err.at(Location::new(FOLLOW_RS, 60)))?;

    loop {
        let response = ctx
            .client
            .receive_response()
            .map_err(|err| err.at(Location::new(FOLLOW_RS, 64)))?;
        match response {
            Response::Stream(stream) => {
                let stdout = io::stdout();
                let mut handle = stdout.lock();
                for (_, text) in stream.logs {
                    let _ = handle.write_all(text.as_bytes());
                }
                let _ = handle.flush();
            }
            Response::Close => break,
            other => logging::error(
                "pueue::client::commands::follow",
                &format!("Received unhandled response message: {other:?}"),
                "pueue/src/client/commands/follow.rs",
                80,
            ),
        }
    }
    Ok(())
}
