//! The `restart` subcommand.

use clap::ArgMatches;

use super::{flag, get_state, string, task_ids, Context};
use crate::error::{Error, Location, Result};
use crate::message::{
    AddRequest, EditableTask, Request, Response, RestartRequest, TaskToRestart,
