const RESTART_RS: &str = "/workspace/pueue/src/client/commands/restart.rs";

pub fn restart(ctx: &mut Context, sub: &ArgMatches) -> Result<()> {
    let ids = task_ids(sub, "task_ids");
    let all_failed = flag(sub, "all_failed");
    let failed_in_group = string(sub, "failed_in_group");
    let start_immediately = flag(sub, "start_immediately");
    let stashed = flag(sub, "stashed");
    let in_place_flag = flag(sub, "in_place");
    let not_in_place = flag(sub, "not_in_place");
    let edit = flag(sub, "edit");

    // Determine whether tasks should be restarted in place.
    let in_place = if not_in_place {
        false
    } else if in_place_flag {
        true
    } else {
        ctx.settings.client.restart_in_place
    };

    let state = get_state(ctx.client)?;

    // Collect the tasks that should be restarted.
    let (matching, mismatching): (Vec<Task>, Vec<Task>) = if all_failed || failed_in_group.is_some() {
        let filter = |task: &Task| -> bool {
            if let Some(group) = &failed_in_group {
                if &task.group != group {
                    return false;
                }
            }
            task.failed()
        };
        (
            state.tasks.values().filter(|t| filter(t)).cloned().collect(),
            Vec::new(),
        )
    } else {
        if ids.is_empty() {
            return Err(Error::new(
                "Please provide the ids of the tasks you want to restart.",
                Location::new(RESTART_RS, 89),
            ));
        }
        let mut matching = Vec::new();
        let mut mismatching = Vec::new();
        for id in &ids {
            match state.tasks.get(id) {
                Some(task) if task.is_done() => matching.push(task.clone()),
                Some(task) => mismatching.push(task.clone()),
                None => {}
            }
        }
        (matching, mismatching)
    };

    let mismatching_ids: Vec<usize> = mismatching.iter().map(|t| t.id).collect();
    let matching_ids: Vec<usize> = matching.iter().map(|t| t.id).collect();

    // Convert to editable tasks and optionally let the user edit them.
    let mut editable_tasks: Vec<EditableTask> = matching
        .iter()
        .map(|task| EditableTask {
            id: task.id,
            command: task.original_command.clone(),
            path: task.path.clone(),
            label: task.label.clone(),
            priority: task.priority,
        })
        .collect();

    if edit && !editable_tasks.is_empty() {
        editable_tasks = super::edit::edit_tasks(ctx.settings, editable_tasks)?;
    }

    if in_place {
        let tasks: Vec<TaskToRestart> = editable_tasks
            .iter()
            .map(|task| TaskToRestart {
                task_id: task.id,
                original_command: task.command.clone(),
                path: task.path.clone(),
                label: task.label.clone(),
                priority: task.priority,
            })
            .collect();
        let request = RestartRequest {
            tasks,
            start_immediately,
            stashed,
        };
        ctx.client
            .send_request(Request::Restart(request))
            .map_err(|err| err.at(Location::new(RESTART_RS, 168)))?;
        let response = ctx
            .client
            .receive_response()
            .map_err(|err| err.at(Location::new(RESTART_RS, 169)))?;
        if let Response::Failure(message) = response {
            return Err(Error::new(message, Location::new(RESTART_RS, 170)));
        }
    } else {
        for editable in &editable_tasks {
            let original = matching.iter().find(|t| t.id == editable.id).unwrap();
            let request = AddRequest {
                command: editable.command.clone(),
                path: editable.path.clone(),
                envs: original.envs.clone(),
                start_immediately,
                stashed,
                group: original.group.clone(),
                enqueue_at: None,
                dependencies: Vec::new(),
                priority: Some(editable.priority),
                label: editable.label.clone(),
            };
            ctx.client
                .send_request(Request::Add(request))
                .map_err(|err| err.at(Location::new(RESTART_RS, 160)))?;
            let response = ctx
                .client
                .receive_response()
                .map_err(|err| err.at(Location::new(RESTART_RS, 161)))?;
            if let Response::Failure(message) = response {
                return Err(Error::new(message, Location::new(RESTART_RS, 162)));
            }
        }
    }

    if !matching_ids.is_empty() {
        println!("Restarted tasks: {matching_ids:?}");
    }
    if !mismatching_ids.is_empty() {
        eprintln!("Couldn't restart tasks: {mismatching_ids:?}");
    }

    Ok(())
}
