/// Let the user edit the given tasks in their `$EDITOR`.
pub fn edit_tasks(settings: &Settings, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let temp_dir = tempfile::Builder::new().prefix(".tmp").tempdir().map_err(|err| {
        Error::new(
