fn edit_toml(settings: &Settings, dir: &Path, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let mut map: BTreeMap<String, TomlTask> = BTreeMap::new();
    let mut ordered: Vec<(usize, TomlTask)> = Vec::new();
    for task in tasks {
        let toml_task = TomlTask {
            id: task.id,
            command: task.command,
            path: task.path,
            label: task.label,
            priority: task.priority,
        };
        ordered.push((task.id, toml_task));
    }
    ordered.sort_by_key(|(id, _)| *id);
    for (id, task) in ordered {
        map.insert(id.to_string(), task);
    }

    let content = serialize_toml(&map);
    let file_path = dir.join("tasks.toml");
    std::fs::write(&file_path, content).map_err(|err| {
        Error::new(
            format!("I/O error at path {:?} while writing tasks to temporary file:\n{err}", file_path),
            Location::new(EDIT_RS, 112),
        )
    })?;

    run_editor(settings, &file_path)?;

    let content = std::fs::read_to_string(&file_path).map_err(|err| {
        Error::new(
            format!("I/O error at path {:?} while reading tasks from temporary file:\n{err}", file_path),
            Location::new(EDIT_RS, 130),
        )
    })?;

    let parsed: BTreeMap<String, TomlTask> = toml::from_str(&content).map_err(|err| {
        Error::new(
            format!("Some error occurred. \nFailed to deserialize tasks to toml:\n{err}"),
            Location::new(EDIT_RS, 135),
        )
    })?;

    let mut tasks: Vec<(usize, EditableTask)> = parsed
        .into_iter()
        .map(|(key, task)| {
            let sort_key = key.parse::<usize>().unwrap_or(task.id);
            (
                sort_key,
                EditableTask {
                    id: task.id,
                    command: task.command,
                    path: task.path,
                    label: task.label,
                    priority: task.priority,
                },
            )
        })
        .collect();
    tasks.sort_by_key(|(key, _)| *key);
    Ok(tasks.into_iter().map(|(_, task)| task).collect())
}

/// Serialize the tasks into the TOML layout used by the editor file.
fn serialize_toml(map: &BTreeMap<String, TomlTask>) -> String {
    let mut sorted: Vec<(&String, &TomlTask)> = map.iter().collect();
    sorted.sort_by_key(|(key, task)| key.parse::<usize>().unwrap_or(task.id));

    let mut blocks = Vec::new();
    for (key, task) in sorted {
        let mut block = String::new();
        block.push_str(&format!("[{key}]\n"));
        block.push_str(&format!("id = {}\n", task.id));
        block.push_str(&format!("command = {}\n", toml_string(&task.command)));
        block.push_str(&format!(
            "path = {}\n",
            toml_string(&task.path.to_string_lossy())
        ));
        if let Some(label) = &task.label {
            block.push_str(&format!("label = {}\n", toml_string(label)));
        }
        block.push_str(&format!("priority = {}\n", task.priority));
        blocks.push(block);
    }
    blocks.join("\n")
}

/// Format a string value like the toml serializer does.
fn toml_string(value: &str) -> String {
    let has_newline = value.contains('\n');
    let has_double_quote = value.contains('"');
    let has_single_quote = value.contains('\'');
    let has_backslash = value.contains('\\');
    let has_control = value
        .chars()
        .any(|c| c.is_control() && c != '\n' && c != '\t');

    if has_newline {
        // Multi-line string
        if !has_control && !value.contains("\"\"\"") && !value.ends_with('"') {
            return format!("\"\"\"\n{}\"\"\"", escape_multiline(value));
        }
        return format!("\"{}\"", escape_basic(value));
    }
    if (has_double_quote || has_backslash) && !has_single_quote && !has_control {
        return format!("'{value}'");
    }
    format!("\"{}\"", escape_basic(value))
}

fn escape_basic(value: &str) -> String {
    let mut out = String::new();
    for c in value.chars() {
        match c {
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if c.is_control() => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn escape_multiline(value: &str) -> String {
    let mut out = String::new();
    for c in value.chars() {
        match c {
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push('\t'),
            '\n' => out.push('\n'),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '"' => out.push('"'),
