                    format!("I/O error at path {:?} while writing {name} file:\n{err}", path),
                    Location::new(EDIT_RS, 236),
                )
            })
        };
        write("command", &task.command)?;
        write("path", &task.path.to_string_lossy())?;
        write("label", task.label.as_deref().unwrap_or(""))?;
        write("priority", &task.priority.to_string())?;
    }

    run_editor(settings, dir)?;

    let mut edited = Vec::new();
    for task in tasks {
        let task_dir = dir.join(task.id.to_string());
        let read = |name: &str, line: u32| -> Result<String> {
            let path = task_dir.join(name);
            std::fs::read_to_string(&path)
                .map(|content| content.trim().to_string())
                .map_err(|err| {
                    Error::new(
                        format!("I/O error at path {:?} while reading {name} file:\n{err}", path),
                        Location::new(EDIT_RS, line),
                    )
                })
        };

        let command = read("command", 262)?;
        let path_str = read("path", 268)?;
        let path = PathBuf::from(&path_str);
        if !path.exists() {
            return Err(Error::new(
                format!(
                    "Found non-existing path '{:?}' after edit for task {}",
                    path, task.id
                ),
                Location::new(EDIT_RS, 273),
            ));
        }
        let label = read("label", 280)?;
        let label = if label.is_empty() { None } else { Some(label) };
        let priority_str = read("priority", 293)?;
        let priority: i32 = priority_str.parse().map_err(|err| {
            Error::new(format!("{err}"), Location::new(EDIT_RS, 297)).context(format!(
                "Failed to parse priority string '{priority_str}' into an integer for task {}",
                task.id
            ))
        })?;

        edited.push(EditableTask {
            id: task.id,
            command,
            path,
            label,
            priority,
        });
    }

    Ok(edited)
}

/// Spawn the user's editor on the given path and wait for it to finish.
fn run_editor(settings: &Settings, path: &Path) -> Result<()> {
    let editor = match std::env::var("EDITOR") {
        Ok(editor) => editor,
        Err(_) => {
            return Err(Error::new(
                "The '$EDITOR' environment variable couldn't be read. Aborting.",
                Location::new(EDIT_RS, 170),
            ))
        }
    };

    let path_str = path.to_string_lossy().to_string();
    let command_string = format!("{editor} {path_str}");

    // Build the shell command, honoring a custom shell command configuration.
    let shell_command: Vec<String> = settings.daemon.shell_command.clone().unwrap_or_else(|| {
        vec![
            "sh".to_string(),
            "-c".to_string(),
            "{{ pueue_command_string }}".to_string(),
        ]
    });
    let shell_command: Vec<String> = shell_command
        .iter()
        .map(|part| render_template(part, &command_string))
        .collect();

    logging::info(
        "pueue::process_helper",
        &format!("Inject environment variables: {{\"PUEUE_EDIT_PATH\": {path_str:?}}}"),
        "pueue/src/process_helper/mod.rs",
        64,
    );

    let (program, args) = shell_command.split_first().unwrap();
    let mut command = Command::new(program);
    command.args(args);
    command.env("PUEUE_EDIT_PATH", &path_str);

    if logging::enabled(logging::Level::Debug) {
        logging::log_event(
            logging::Level::Debug,
            "pueue::process_helper",
            "Prepared command before spawn",
            &[logging::Field {
                name: "command",
                pretty_value: format!("{command:#?}"),
                value: format!("{command:?}"),
            }],
            "pueue/src/process_helper/mod.rs",
            70,
        );
    }

    let status = command.status().map_err(|err| {
        Error::new(
            format!("Failed to spawn editor:\n{err}"),
            Location::new(EDIT_RS, 185),
        )
    })?;

    if !status.success() {
        return Err(Error::new(
            "The editor exited with a non-zero code. Aborting.",
            Location::new(EDIT_RS, 188),
        ));
    }
    Ok(())
}

/// Minimal handlebars-like replacement of `{{ pueue_command_string }}`.
fn render_template(template: &str, command_string: &str) -> String {
    let mut out = String::new();
    let mut rest = template;
    while let Some(start) = rest.find("{{") {
        out.push_str(&rest[..start]);
        let after = &rest[start + 2..];
        if let Some(end) = after.find("}}") {
            let name = after[..end].trim();
            if name == "pueue_command_string" {
                out.push_str(command_string);
            }
            rest = &after[end + 2..];
        } else {
            out.push_str(&rest[start..]);
            rest = "";
        }
    }
    out.push_str(rest);
    out
}
