                Error::new(format!("{err}"), Location::new(PUEUE_RS, 125))
                    .context(format!("Failed to generate completions for {shell_name}"))
            })?;
        }
        None => {
            let stdout = std::io::stdout();
            let mut handle = stdout.lock();
            let _ = handle.write_all(&generated);
            let _ = handle.flush();
        }
    }
    Ok(())
}

fn generate_clap(shell: Shell, cmd: &mut Command) -> Vec<u8> {
    let mut buffer = Vec::new();
    clap_complete::generate(shell, cmd, "pueue", &mut buffer);
    buffer
}

fn generate_nushell(cmd: &mut Command) -> Vec<u8> {
    cmd.build();
    let mut out = String::new();
    out.push_str("module completions {\n\n");
    nushell_command(&mut out, cmd, false);
    out.push_str("}\n\nexport use completions *\n");
    out.into_bytes()
}

fn is_path_hint(hint: ValueHint) -> bool {
    matches!(
        hint,
        ValueHint::AnyPath
            | ValueHint::FilePath
            | ValueHint::DirPath
            | ValueHint::ExecutablePath
    )
}

fn nushell_command(out: &mut String, cmd: &Command, is_subcommand: bool) {
    let bin_name = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name()).to_string();

    // Possible value completers.
    for arg in cmd.get_arguments() {
        if arg.is_hide_set() {
            continue;
        }
        let values: Vec<String> = arg
            .get_possible_values()
            .iter()
            .filter(|v| !v.is_hide_set())
            .map(|v| format!("\"{}\"", v.get_name()))
            .collect();
        if values.is_empty() {
            continue;
        }
        out.push_str(&format!(
            "  def \"nu-complete {bin_name} {}\" [] {{\n    [ {} ]\n  }}\n\n",
            arg.get_id(),
            values.join(" ")
        ));
    }

    if let Some(about) = cmd.get_about() {
        let about = about.to_string().replace('\n', " ");
        out.push_str(&format!("  # {about}\n"));
    }

    let name = if is_subcommand {
        format!("\"{bin_name}\"")
    } else {
        bin_name.clone()
    };
    out.push_str(&format!("  export extern {name} [\n"));

    let mut options = Vec::new();
    let mut positionals = Vec::new();
    for arg in cmd.get_arguments() {
        if arg.is_hide_set() {
            continue;
        }
        let takes_values = arg.get_num_args().map(|n| n.takes_values()).unwrap_or(false);
        let has_values = !arg.get_possible_values().is_empty();
        let value_type = {
            let base = if is_path_hint(arg.get_value_hint()) {
                "path"
            } else {
                "string"
            };
            if has_values {
                format!("{base}@\"nu-complete {bin_name} {}\"", arg.get_id())
            } else {
                base.to_string()
            }
        };
        let help = arg
            .get_help()
            .map(|h| h.to_string().replace('\n', " "))
            .unwrap_or_default();

        if arg.is_positional() {
            let multiple = arg
                .get_num_args()
                .map(|n| n.max_values() > 1)
                .unwrap_or(false);
            let mut text = String::new();
            if multiple {
                text.push_str("...");
            }
            text.push_str(arg.get_id().as_str());
            if !arg.is_required_set() && !multiple {
                text.push('?');
            }
            text.push_str(&format!(": {value_type}"));
            positionals.push(format_line(&text, &help));
        } else {
            let mut text = String::new();
            if let Some(long) = arg.get_long() {
                text.push_str(&format!("--{long}"));
                if let Some(short) = arg.get_short() {
                    text.push_str(&format!("(-{short})"));
                }
            } else if let Some(short) = arg.get_short() {
                text.push_str(&format!("-{short}"));
            }
            if takes_values {
                text.push_str(&format!(": {value_type}"));
            }
            options.push(format_line(&text, &help));
        }
    }
    for line in options.into_iter().chain(positionals) {
        out.push_str(&line);
    }
    out.push_str("  ]\n\n");

    for sub in cmd.get_subcommands() {
        nushell_command(out, sub, true);
    }
}

fn format_line(text: &str, help: &str) -> String {
    if help.is_empty() {
        format!("    {text}\n")
    } else {
        format!("    {text:<25} # {help}\n")
    }
}
