//! Parsing of `--delay` expressions: either a number of seconds or a human friendly
//! date/time expression.

use chrono::{DateTime, Datelike, Duration, Local, Months, NaiveDate, NaiveTime, TimeZone, Weekday};

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Num(u32),
    Iden(String),
    Char(char),
    End,
}

struct Scanner {
    tokens: Vec<Token>,
    pos: usize,
}

impl Scanner {
    fn new(input: &str) -> Result<Self, ()> {
        let mut tokens = Vec::new();
        let chars: Vec<char> = input.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            let c = chars[i];
            if c.is_whitespace() {
                i += 1;
                continue;
            }
            if c.is_ascii_digit() {
                let start = i;
                while i < chars.len() && chars[i].is_ascii_digit() {
                    i += 1;
                }
                let digits: String = chars[start..i].iter().collect();
                if digits.len() > 4 {
                    return Err(());
                }
                tokens.push(Token::Num(digits.parse().map_err(|_| ())?));
                continue;
            }
            if c.is_alphabetic() {
                let start = i;
                while i < chars.len() && chars[i].is_alphabetic() {
                    i += 1;
                }
                tokens.push(Token::Iden(chars[start..i].iter().collect()));
                continue;
            }
            tokens.push(Token::Char(c));
            i += 1;
        }
        tokens.push(Token::End);
        Ok(Scanner { tokens, pos: 0 })
    }

    fn get(&mut self) -> Token {
        let token = self.tokens.get(self.pos).cloned().unwrap_or(Token::End);
        if self.pos < self.tokens.len() {
            self.pos += 1;
        }
        token
    }

    fn peek(&self) -> Token {
        self.tokens.get(self.pos).cloned().unwrap_or(Token::End)
    }

    fn get_num(&mut self) -> Result<u32, ()> {
        match self.get() {
            Token::Num(n) => Ok(n),
            _ => Err(()),
        }
    }

    /// Return the raw digit string of the next number token (used for fractions).
    fn get_digits(&mut self, input: &str) -> Result<String, ()> {
        let _ = input;
        match self.get() {
            Token::Num(n) => Ok(n.to_string()),
            _ => Err(()),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Unit {
    Second,
    Minute,
    Hour,
    Day,
    Week,
    Month,
    Year,
}

fn time_unit(name: &str) -> Option<Unit> {
    let prefix: String = name.chars().take(2).collect();
    Some(match prefix.as_str() {
        "s" | "se" => Unit::Second,
        "m" | "mi" => Unit::Minute,
        "h" | "ho" => Unit::Hour,
        "d" | "da" => Unit::Day,
        "w" | "we" => Unit::Week,
        "mo" => Unit::Month,
        "y" | "ye" => Unit::Year,
        _ => return None,
    })
}

fn week_day(name: &str) -> Option<Weekday> {
    if name.len() < 3 {
        return None;
    }
    let prefix: String = name.chars().take(3).collect();
    Some(match prefix.as_str() {
        "sun" => Weekday::Sun,
        "mon" => Weekday::Mon,
        "tue" => Weekday::Tue,
        "wed" => Weekday::Wed,
        "thu" => Weekday::Thu,
        "fri" => Weekday::Fri,
        "sat" => Weekday::Sat,
        _ => return None,
    })
}

fn month_name(name: &str) -> Option<u32> {
    if name.len() < 3 {
        return None;
    }
    let prefix: String = name.chars().take(3).collect();
    Some(match prefix.as_str() {
        "jan" => 1,
        "feb" => 2,
        "mar" => 3,
        "apr" => 4,
        "may" => 5,
        "jun" => 6,
        "jul" => 7,
        "aug" => 8,
        "sep" => 9,
        "oct" => 10,
        "nov" => 11,
        "dec" => 12,
        _ => return None,
    })
}

#[derive(Debug, Clone)]
enum DateSpec {
    /// A fixed date.
    Absolute(NaiveDate),
    /// Relative to now by a number of units.
    Relative(i64, Unit),
    /// Today/tomorrow/yesterday: relative days keeping the time of day.
    Days(i64),
    /// A weekday. The direction decides whether to look forward or backward.
    WeekDay(Weekday, i32),
}

#[derive(Debug, Clone, Default)]
struct TimeSpec {
    hour: u32,
    min: u32,
    sec: u32,
    micros: u32,
    /// Timezone offset in seconds, if an explicit offset/`Z` was given.
    offset: Option<i64>,
}

struct Parser {
    s: Scanner,
}

fn expand_year(year: u32) -> i32 {
    if year < 100 {
        if year <= 40 {
            2000 + year as i32
        } else {
            1900 + year as i32
        }
    } else {
        year as i32
    }
}

impl Parser {
    /// Parse the whole expression into a date and time spec.
    fn parse(&mut self, now: DateTime<Local>) -> Result<(Option<DateSpec>, Option<TimeSpec>), ()> {
        let token = self.s.get();
        match token {
            Token::Iden(name) => self.parse_iden(name, now),
            Token::Num(n) => self.parse_number(n, now),
            _ => Err(()),
        }
    }

    fn parse_iden(&mut self, name: String, now: DateTime<Local>) -> Result<(Option<DateSpec>, Option<TimeSpec>), ()> {
        let lower = name.to_lowercase();
        match lower.as_str() {
            "now" | "today" => {
                let time = self.parse_time_strict()?;
                return Ok((Some(DateSpec::Days(0)), time));
            }
            "tomorrow" => {
                let time = self.parse_time_strict()?;
                return Ok((Some(DateSpec::Days(1)), time));
            }
            "yesterday" => {
                let time = self.parse_time_strict()?;
                return Ok((Some(DateSpec::Days(-1)), time));
            }
            "next" | "last" | "this" => {
                let direction: i32 = match lower.as_str() {
                    "next" => 1,
                    "last" => -1,
                    _ => 0,
                };
                return match self.s.get() {
                    Token::Iden(next) => {
                        let next_lower = next.to_lowercase();
                        if let Some(weekday) = week_day(&next_lower) {
                            let time = self.parse_time_strict()?;
                            Ok((Some(DateSpec::WeekDay(weekday, direction)), time))
                        } else if let Some(unit) = time_unit(&next_lower) {
                            self.parse_relative(direction as i64, unit)
                        } else {
                            Err(())
                        }
                    }
                    Token::Num(n) => self.parse_number(n, now),
                    _ => Err(()),
                };
            }
            _ => {}
        }

        if let Some(weekday) = week_day(&lower) {
            let time = self.parse_time_strict()?;
            return Ok((Some(DateSpec::WeekDay(weekday, 0)), time));
        }

        if let Some(month) = month_name(&lower) {
            // Optional day, optional ", year" and time.
            return match self.s.get() {
                Token::Num(day) => {
                    let (year, time) = match self.s.peek() {
                        Token::Char(',') => {
                            self.s.get();
                            let year = self.s.get_num()?;
                            let time = self.parse_time_strict()?;
                            (year as i32, time)
                        }
                        _ => {
                            let time = self.parse_time_strict()?;
                            (now.year(), time)
                        }
                    };
                    let date = NaiveDate::from_ymd_opt(year, month, day).ok_or(())?;
                    Ok((Some(DateSpec::Absolute(date)), time))
                }
                _ => {
                    let date = NaiveDate::from_ymd_opt(now.year(), month, 1).ok_or(())?;
                    Ok((Some(DateSpec::Absolute(date)), None))
                }
            };
        }

        if let Some(unit) = time_unit(&lower) {
            return self.parse_relative(0, unit);
        }

        Err(())
    }

    fn parse_number(&mut self, n: u32, now: DateTime<Local>) -> Result<(Option<DateSpec>, Option<TimeSpec>), ()> {
        match self.s.get() {
            Token::Char('/') => {
                // American style month/day[/year]
                let day = self.s.get_num()?;
                let year = match self.s.peek() {
                    Token::Char('/') => {
                        self.s.get();
                        expand_year(self.s.get_num()?)
                    }
                    _ => now.year(),
                };
                let date = NaiveDate::from_ymd_opt(year, n, day).ok_or(())?;
                let time = self.parse_time_strict()?;
                Ok((Some(DateSpec::Absolute(date)), time))
            }
            Token::Char('-') => {
                // ISO style year-month-day
                let month = self.s.get_num()?;
                match self.s.get() {
                    Token::Char('-') => {}
                    _ => return Err(()),
                }
                let day = self.s.get_num()?;
                let date = NaiveDate::from_ymd_opt(n as i32, month, day).ok_or(())?;
                // Optional 'T' separator.
                if let Token::Iden(iden) = self.s.peek() {
                    if iden == "T" {
                        self.s.get();
                    }
                }
                let time = self.parse_time_strict()?;
                Ok((Some(DateSpec::Absolute(date)), time))
            }
            Token::Char(':') => {
                let time = self.parse_time_after_hour(n, ':')?;
                Ok((None, Some(time)))
            }
            Token::Char('.') => {
                let time = self.parse_time_after_hour(n, '.')?;
                Ok((None, Some(time)))
            }
            Token::Iden(name) => {
                let lower = name.to_lowercase();
                if lower == "am" || lower == "pm" {
                    let time = apply_ampm(TimeSpec { hour: n, ..Default::default() }, &lower)?;
                    return Ok((None, Some(time)));
                }
                if let Some(month) = month_name(&lower) {
                    // "25 Dec [2027]"
                    return match self.s.get() {
                        Token::Num(year) => {
                            let date = NaiveDate::from_ymd_opt(year as i32, month, n).ok_or(())?;
                            let time = self.parse_time_strict()?;
                            Ok((Some(DateSpec::Absolute(date)), time))
                        }
                        _ => {
                            let date = NaiveDate::from_ymd_opt(now.year(), month, n).ok_or(())?;
                            Ok((Some(DateSpec::Absolute(date)), None))
                        }
                    };
                }
                if let Some(unit) = time_unit(&lower) {
                    return self.parse_relative(n as i64, unit);
                }
                Err(())
            }
            Token::End => {
                // A bare number is interpreted as a year.
                let date = NaiveDate::from_ymd_opt(n as i32, 1, 1).ok_or(())?;
                Ok((Some(DateSpec::Absolute(date)), None))
            }
            _ => Err(()),
        }
    }

    /// Parse what follows a relative unit: optional `ago` and an optional time.
    fn parse_relative(&mut self, amount: i64, unit: Unit) -> Result<(Option<DateSpec>, Option<TimeSpec>), ()> {
        match self.s.get() {
            Token::End => Ok((Some(DateSpec::Relative(amount, unit)), None)),
            Token::Iden(name) => {
                if name.to_lowercase() == "ago" {
                    let time = self.parse_time_strict()?;
                    Ok((Some(DateSpec::Relative(-amount, unit)), time))
                } else {
                    Err(())
                }
            }
            Token::Num(hour) => {
                let time = match self.s.get() {
                    Token::Char(sep @ (':' | '.')) => self.parse_time_after_hour(hour, sep)?,
                    _ => return Err(()),
                };
                Ok((Some(DateSpec::Relative(amount, unit)), Some(time)))
            }
            _ => Ok((Some(DateSpec::Relative(amount, unit)), None)),
        }
    }

    /// Parse an optional time. Anything but a valid time or the end of input is an error.
    fn parse_time_strict(&mut self) -> Result<Option<TimeSpec>, ()> {
        match self.s.get() {
            Token::End => Ok(None),
            Token::Num(hour) => match self.s.get() {
                Token::Iden(name) => {
                    let lower = name.to_lowercase();
                    if lower == "am" || lower == "pm" {
                        Ok(Some(apply_ampm(TimeSpec { hour, ..Default::default() }, &lower)?))
                    } else {
                        Err(())
                    }
                }
                Token::Char(sep @ (':' | '.')) => Ok(Some(self.parse_time_after_hour(hour, sep)?)),
                _ => Err(()),
            },
            _ => Err(()),
        }
    }

    /// Parse the remainder of a time after `hour` and the given separator.
    fn parse_time_after_hour(&mut self, hour: u32, sep: char) -> Result<TimeSpec, ()> {
        let mut time = TimeSpec { hour, ..Default::default() };
        let min = self.s.get_num()?;
        if min >= 60 {
            return Err(());
        }
        time.min = min;

        if sep == '.' {
            return match self.s.get() {
                Token::End => Ok(time),
                Token::Iden(name) => {
                    let lower = name.to_lowercase();
                    if lower == "am" || lower == "pm" {
                        apply_ampm(time, &lower)
                    } else {
                        Err(())
                    }
                }
                _ => Err(()),
            };
        }

        match self.s.get() {
            Token::End => Ok(time),
            Token::Iden(name) => {
                let lower = name.to_lowercase();
                if lower == "am" || lower == "pm" {
                    apply_ampm(time, &lower)
                } else if lower == "z" {
                    time.offset = Some(0);
                    Ok(time)
                } else {
                    Err(())
                }
            }
            Token::Char(':') => {
                let sec = self.s.get_num()?;
                if sec >= 60 {
                    return Err(());
                }
                time.sec = sec;
                let mut next = self.s.get();
                if next == Token::Char('.') {
                    let digits = self.s.get_digits("")?;
                    time.micros = digits.parse().map_err(|_| ())?;
                    next = self.s.get();
                }
                match next {
                    Token::End => Ok(time),
                    Token::Iden(name) => {
                        let lower = name.to_lowercase();
                        if lower == "am" || lower == "pm" {
                            apply_ampm(time, &lower)
                        } else if lower == "z" {
                            time.offset = Some(0);
                            Ok(time)
                        } else {
                            Err(())
                        }
                    }
                    Token::Char(sign @ ('+' | '-')) => {
                        let offset = self.parse_offset()?;
                        time.offset = Some(if sign == '-' { -offset } else { offset });
                        Ok(time)
                    }
                    _ => Err(()),
                }
            }
            _ => Err(()),
        }
    }

    /// Parse a timezone offset like `02:00` or `0200`. Returns seconds.
    fn parse_offset(&mut self) -> Result<i64, ()> {
        let first = self.s.get_num()?;
        let (hours, minutes) = match self.s.peek() {
            Token::Char(':') => {
                self.s.get();
                let minutes = self.s.get_num()?;
                (first, minutes)
            }
            _ => (first / 100, first % 100),
        };
        Ok(hours as i64 * 3600 + minutes as i64 * 60)
    }
}

fn apply_ampm(mut time: TimeSpec, ampm: &str) -> Result<TimeSpec, ()> {
    if ampm == "pm" {
        if time.hour != 12 {
            time.hour += 12;
        }
    } else if time.hour == 12 {
        time.hour = 0;
    }
    Ok(time)
}

fn time_of(time: &TimeSpec) -> Duration {
    Duration::seconds(time.hour as i64 * 3600 + time.min as i64 * 60 + time.sec as i64)
        + Duration::microseconds(time.micros as i64)
}

/// Combine a date with a time spec into a local date time.
fn combine(date: NaiveDate, time: &TimeSpec) -> Result<DateTime<Local>, ()> {
    let naive = date.and_time(NaiveTime::from_hms_opt(0, 0, 0).unwrap());
    let naive = naive.checked_add_signed(time_of(time)).ok_or(())?;
    match time.offset {
        Some(offset) => {
            let utc = naive.checked_sub_signed(Duration::seconds(offset)).ok_or(())?;
            let utc = chrono::Utc.from_utc_datetime(&utc);
            Ok(utc.with_timezone(&Local))
        }
        None => Local.from_local_datetime(&naive).single().ok_or(()),
    }
}

fn weekday_date(now: DateTime<Local>, weekday: Weekday, direction: i32) -> NaiveDate {
    let today = now.date_naive();
    let current = today.weekday().num_days_from_monday() as i64;
    let target = weekday.num_days_from_monday() as i64;
    if direction < 0 {
        // The most recent occurrence, including today.
        let mut diff = current - target;
        if diff < 0 {
            diff += 7;
        }
        today - Duration::days(diff)
    } else {
        // The next occurrence after today.
        let mut diff = target - current;
        if diff <= 0 {
            diff += 7;
        }
        today + Duration::days(diff)
    }
}

fn to_date_time(
    date: Option<DateSpec>,
    time: Option<TimeSpec>,
    now: DateTime<Local>,
) -> Result<DateTime<Local>, ()> {
    let midnight = TimeSpec::default();
    let now_time = TimeSpec {
        hour: now.hour(),
        min: now.minute(),
        sec: now.second(),
        micros: now.nanosecond() / 1000,
        offset: None,
    };

    match date {
        None => {
            let time = time.unwrap_or_default();
            combine(now.date_naive(), &time)
        }
        Some(DateSpec::Absolute(date)) => combine(date, &time.unwrap_or(midnight)),
        Some(DateSpec::Days(days)) => {
            let base = now.checked_add_signed(Duration::days(days)).ok_or(())?;
            match time {
                Some(time) => combine(base.date_naive(), &time),
                None => Ok(base),
            }
        }
        Some(DateSpec::WeekDay(weekday, direction)) => {
            let date = weekday_date(now, weekday, direction);
            combine(date, &time.unwrap_or(midnight))
        }
        Some(DateSpec::Relative(amount, unit)) => match unit {
            Unit::Second => now.checked_add_signed(Duration::seconds(amount)).ok_or(()),
            Unit::Minute => now.checked_add_signed(Duration::minutes(amount)).ok_or(()),
            Unit::Hour => now.checked_add_signed(Duration::hours(amount)).ok_or(()),
            Unit::Day | Unit::Week => {
                let days = if unit == Unit::Week { amount * 7 } else { amount };
                let base = now.checked_add_signed(Duration::days(days)).ok_or(())?;
                match time {
                    Some(time) => combine(base.date_naive(), &time),
                    None => Ok(base),
                }
            }
            Unit::Month | Unit::Year => {
                let months = if unit == Unit::Year { amount * 12 } else { amount };
                let date = now.date_naive();
                let date = if months >= 0 {
                    date.checked_add_months(Months::new(months as u32)).ok_or(())?
                } else {
                    date.checked_sub_months(Months::new((-months) as u32)).ok_or(())?
                };
                combine(date, &time.unwrap_or(midnight))
            }
        },
    }
}

/// Parse a date expression relative to `now`.
pub fn parse_date_string(input: &str, now: DateTime<Local>) -> Result<DateTime<Local>, ()> {
    let scanner = Scanner::new(input)?;
    let mut parser = Parser { s: scanner };
    let (date, time) = parser.parse(now)?;
    let result = to_date_time(date, time, now)?;
    if result.year() > 9999 + 1 || result.year() < -1 {
        // Keep chrono's formatting limits in mind.
    }
    Ok(result)
}

/// Parse the `--delay` argument: a number of seconds or a date expression.
pub fn parse_delay_until(src: &str) -> Result<DateTime<Local>, String> {
    if let Ok(seconds) = src.parse::<i64>() {
        return Local::now()
            .checked_add_signed(Duration::seconds(seconds))
            .ok_or_else(|| "could not parse as seconds or date expression".to_string());
    }
    parse_date_string(src, Local::now())
        .map_err(|_| "could not parse as seconds or date expression".to_string())
}
