import struct, sys
sys.path.insert(0, '/tmp')
from snappy import crc32c, masked

def varint(n):
    out = b""
    while True:
        b = n & 0x7f
        n >>= 7
        if n:
            out += bytes([b | 0x80])
        else:
            out += bytes([b])
            return out

def emit_literal(data):
    n = len(data) - 1
    if n < 60:
        return bytes([n << 2]) + data
    elif n < 256:
        return bytes([60 << 2, n]) + data
    elif n < 65536:
        return bytes([61 << 2]) + struct.pack("<H", n) + data
    else:
        return bytes([62 << 2]) + struct.pack("<I", n)[:3] + data

def emit_copy(offset, length):
    out = b""
    while length > 0:
        if 4 <= length <= 11 and offset < 2048:
            out += bytes([1 | ((length - 4) << 2) | ((offset >> 8) << 5), offset & 0xff])
            return out
        l = min(length, 64)
        if length - l in (1, 2, 3) and l > 4:
            l = length - 4  # avoid tiny remainders (<4 not encodable with 1-byte copy)
        if offset < 65536:
            out += bytes([2 | ((l - 1) << 2)]) + struct.pack("<H", offset)
        else:
            out += bytes([3 | ((l - 1) << 2)]) + struct.pack("<I", offset)
        length -= l
    return out

def compress_block(data):
    out = varint(len(data))
    i = 0
    lit_start = 0
    table = {}
    n = len(data)
    while i + 4 <= n:
        key = data[i:i+4]
        cand = table.get(key)
        table[key] = i
        if cand is not None and i - cand < 65536:
            # extend match
            l = 4
            while i + l < n and data[cand + l] == data[i + l] and l < 64:
                l += 1
            if i > lit_start:
                out += emit_literal(data[lit_start:i])
            out += emit_copy(i - cand, l)
            i += l
            lit_start = i
        else:
            i += 1
    if lit_start < n:
        out += emit_literal(data[lit_start:])
    return out

def frame_encode_compressed(data):
    out = b"\xff\x06\x00\x00sNaPpY"
    i = 0
    while i < len(data):
        chunk = data[i:i+65536]
        i += 65536
        comp = compress_block(chunk)
        body = struct.pack("<I", masked(crc32c(chunk))) + comp
        out += b"\x00" + struct.pack("<I", len(body))[:3] + body
    return out
